/**
 * Tiny procedural sound engine. No audio assets, no network.
 * Everything is synthesised from oscillators and noise buffers.
 */
export class SoundEngine {
  constructor() {
    this.ctx = null;
    this.enabled = true;
    this.started = false;
    this.noise = null;
    this.crowd = null;
    this.crowdGain = null;
  }

  init() {
    if (this.ctx) {
      if (this.ctx.state === "suspended") this.ctx.resume();
      return;
    }
    const Ctx = window.AudioContext || window.webkitAudioContext;
    if (!Ctx) return;
    this.ctx = new Ctx();
    this.master = this.ctx.createGain();
    this.master.gain.value = this.enabled ? 0.8 : 0;
    this.master.connect(this.ctx.destination);
    this.noise = this.makeNoise(2.5, 0.5);
  }

  setEnabled(enabled) {
    this.enabled = enabled;
    if (this.master) {
      this.master.gain.setTargetAtTime(enabled ? 0.8 : 0, this.ctx.currentTime, 0.03);
    }
    if (enabled) this.init();
  }

  makeNoise(seconds, decay = 1) {
    const rate = this.ctx.sampleRate;
    const length = Math.floor(rate * seconds);
    const buffer = this.ctx.createBuffer(1, length, rate);
    const data = buffer.getChannelData(0);
    let last = 0;
    for (let i = 0; i < length; i++) {
      const t = i / length;
      const white = Math.random() * 2 - 1;
      last = last * 0.86 + white * 0.14;
      data[i] = last * Math.pow(1 - t, decay);
    }
    return buffer;
  }

  startCrowd() {
    this.init();
    if (!this.ctx || this.crowd) return;
    const src = this.ctx.createBufferSource();
    src.buffer = this.makeNoise(6, 0.05);
    src.loop = true;
    const low = this.ctx.createBiquadFilter();
    low.type = "lowpass";
    low.frequency.value = 680;
    const high = this.ctx.createBiquadFilter();
    high.type = "highpass";
    high.frequency.value = 120;
    const gain = this.ctx.createGain();
    gain.gain.value = 0.028;
    src.connect(low).connect(high).connect(gain).connect(this.master);
    src.start();
    this.crowd = src;
    this.crowdGain = gain;
    this.started = true;
  }

  stopCrowd() {
    if (!this.crowd) return;
    try {
      this.crowd.stop();
    } catch {
      /* already stopped */
    }
    this.crowd = null;
    this.crowdGain = null;
  }

  cheer(intensity = 1) {
    if (!this.ctx || !this.crowdGain) return;
    const t = this.ctx.currentTime;
    this.crowdGain.gain.cancelScheduledValues(t);
    this.crowdGain.gain.setTargetAtTime(0.035 + 0.085 * intensity, t, 0.08);
    this.crowdGain.gain.setTargetAtTime(0.028, t + 0.7, 1.4);
  }

  tone({ freq = 100, endFreq = 45, type = "sine", dur = 0.3, gain = 0.3, attack = 0.004, delay = 0 }) {
    if (!this.ctx) return;
    const t = this.ctx.currentTime + delay;
    const osc = this.ctx.createOscillator();
    const amp = this.ctx.createGain();
    osc.type = type;
    osc.frequency.setValueAtTime(freq, t);
    osc.frequency.exponentialRampToValueAtTime(Math.max(20, endFreq), t + dur);
    amp.gain.setValueAtTime(0.0001, t);
    amp.gain.exponentialRampToValueAtTime(gain, t + attack);
    amp.gain.exponentialRampToValueAtTime(0.0001, t + dur);
    osc.connect(amp).connect(this.master);
    osc.start(t);
    osc.stop(t + dur + 0.03);
  }

  burst({ dur = 0.12, freq = 1100, q = 0.8, gain = 0.24, type = "bandpass", delay = 0 }) {
    if (!this.ctx) return;
    const t = this.ctx.currentTime + delay;
    const src = this.ctx.createBufferSource();
    src.buffer = this.noise;
    const filter = this.ctx.createBiquadFilter();
    filter.type = type;
    filter.frequency.setValueAtTime(freq, t);
    filter.frequency.exponentialRampToValueAtTime(Math.max(120, freq * 0.28), t + dur);
    filter.Q.value = q;
    const amp = this.ctx.createGain();
    amp.gain.setValueAtTime(gain, t);
    amp.gain.exponentialRampToValueAtTime(0.0001, t + dur);
    src.connect(filter).connect(amp).connect(this.master);
    src.start(t, 0.2, dur + 0.02);
    src.stop(t + dur + 0.03);
  }

  punch(power = 1, blocked = false, delay = 0) {
    if (!this.ctx) return;
    if (blocked) {
      this.burst({ dur: 0.11, freq: 2400, q: 1.2, gain: 0.2, delay });
      this.tone({ freq: 160, endFreq: 90, type: "square", dur: 0.08, gain: 0.08, delay });
      return;
    }
    this.tone({ freq: 105 + power * 22, endFreq: 42, type: "sine", dur: 0.22, gain: 0.32 * power, delay });
    this.burst({ dur: 0.13, freq: 1500, q: 0.7, gain: 0.2 * power, delay });
    this.tone({ freq: 230, endFreq: 80, type: "triangle", dur: 0.09, gain: 0.12, delay });
  }

  kick() {
    if (!this.ctx) return;
    this.burst({ dur: 0.17, freq: 900, q: 1.1, gain: 0.24 });
    this.tone({ freq: 92, endFreq: 34, type: "sine", dur: 0.34, gain: 0.28 });
  }

  whoosh(heavy = false) {
    if (!this.ctx) return;
    this.burst({ dur: heavy ? 0.16 : 0.1, freq: heavy ? 760 : 1250, q: 0.7, gain: 0.075, type: "bandpass" });
  }

  takedown() {
    if (!this.ctx) return;
    this.tone({ freq: 76, endFreq: 30, type: "sine", dur: 0.45, gain: 0.42 });
    this.burst({ dur: 0.3, freq: 560, q: 0.5, gain: 0.26, type: "lowpass" });
    this.cheer(0.65);
  }

  bell(count = 1) {
    this.init();
    if (!this.ctx) return;
    for (let i = 0; i < count; i++) {
      const delay = i * 0.48;
      [1, 2.01, 3.03, 4.18].forEach((mult, index) => {
        this.tone({
          freq: 690 * mult,
          endFreq: 690 * mult * 0.996,
          type: "sine",
          dur: 1.15 - index * 0.16,
          gain: 0.16 / (index + 1),
          attack: 0.003,
          delay,
        });
      });
    }
    this.cheer(0.8);
  }

  ko() {
    if (!this.ctx) return;
    this.tone({ freq: 58, endFreq: 24, type: "sine", dur: 1.6, gain: 0.5 });
    this.burst({ dur: 0.9, freq: 320, q: 0.4, gain: 0.22, type: "lowpass" });
    this.cheer(1.5);
  }

  ui(up = true) {
    if (!this.ctx) return;
    this.tone({ freq: up ? 740 : 440, endFreq: up ? 940 : 360, type: "triangle", dur: 0.07, gain: 0.055 });
  }

  step() {
    if (!this.ctx) return;
    this.burst({ dur: 0.05, freq: 210, q: 0.8, gain: 0.035, type: "lowpass" });
  }
}

import * as THREE from "three";

const TAU = Math.PI * 2;
const OCT_ANGLE = Math.PI / 8;

function makeCanvas(size = 1024) {
  const canvas = document.createElement("canvas");
  canvas.width = size;
  canvas.height = size;
  return canvas;
}

function makeMatTexture(canvas) {
  const texture = new THREE.CanvasTexture(canvas);
  texture.colorSpace = THREE.SRGBColorSpace;
  texture.anisotropy = 8;
  return texture;
}

function roundedRect(ctx, x, y, w, h, r) {
  ctx.beginPath();
  ctx.moveTo(x + r, y);
  ctx.arcTo(x + w, y, x + w, y + h, r);
  ctx.arcTo(x + w, y + h, x, y + h, r);
  ctx.arcTo(x, y + h, x, y, r);
  ctx.arcTo(x, y, x + w, y, r);
  ctx.closePath();
}

export class Arena {
  constructor(scene, renderer) {
    this.scene = scene;
    this.renderer = renderer;
    this.group = new THREE.Group();
    this.group.name = "arena";
    scene.add(this.group);
    this.octagonRadius = 5.62;
    this.cageHeight = 2.95;
    this.flashes = [];
    this.time = 0;
    this.screenText = { left: "KAI MORENO", right: "MARCUS OKAFOR", round: "FIGHT NIGHT 07" };
    this._build();
  }

  _build() {
    this._materials();
    this._platform();
    this._cage();
    this._outside();
    this._crowd();
    this._jumbotron();
    this._lights();
    this._atmosphere();
    this._referee();
  }

  _materials() {
    this.matBlack = new THREE.MeshStandardMaterial({ color: 0x090a0d, roughness: 0.78, metalness: 0.18 });
    this.matPad = new THREE.MeshStandardMaterial({ color: 0x15171c, roughness: 0.92, metalness: 0 });
    this.matSteel = new THREE.MeshStandardMaterial({ color: 0x626975, roughness: 0.32, metalness: 0.92 });
    this.matRedPad = new THREE.MeshStandardMaterial({ color: 0x9c1019, roughness: 0.56, metalness: 0.08, emissive: 0x230003, emissiveIntensity: 0.6 });
    this.matBluePad = new THREE.MeshStandardMaterial({ color: 0x1b3d8f, roughness: 0.56, metalness: 0.08, emissive: 0x020b22, emissiveIntensity: 0.6 });
  }

  _floorTexture() {
    const canvas = makeCanvas(1024);
    const ctx = canvas.getContext("2d");
    const g = ctx.createRadialGradient(512, 470, 20, 512, 512, 600);
    g.addColorStop(0, "#2a2c31");
    g.addColorStop(0.48, "#202227");
    g.addColorStop(1, "#101115");
    ctx.fillStyle = g;
    ctx.fillRect(0, 0, 1024, 1024);

    // Fine mat texture
    ctx.globalAlpha = 0.06;
    for (let i = 0; i < 12000; i++) {
      const c = Math.random() > 0.5 ? 255 : 0;
      ctx.fillStyle = `rgb(${c},${c},${c})`;
      ctx.fillRect(Math.random() * 1024, Math.random() * 1024, 1, 1);
    }
    ctx.globalAlpha = 1;

    // Octagon geometry lines
    ctx.strokeStyle = "rgba(255,255,255,.055)";
    ctx.lineWidth = 2;
    for (let r = 175; r <= 460; r += 95) {
      ctx.beginPath();
      for (let i = 0; i <= 8; i++) {
        const a = OCT_ANGLE + (i * TAU) / 8;
        const x = 512 + Math.cos(a) * r;
        const y = 512 + Math.sin(a) * r;
        if (i === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      }
      ctx.stroke();
    }

    // Center mark
    ctx.save();
    ctx.translate(512, 512);
    ctx.strokeStyle = "rgba(255,47,56,.5)";
    ctx.lineWidth = 4;
    ctx.beginPath();
    ctx.arc(0, 0, 130, 0, TAU);
    ctx.stroke();
    ctx.strokeStyle = "rgba(255,255,255,.12)";
    ctx.lineWidth = 1.5;
    ctx.beginPath();
    ctx.arc(0, 0, 148, 0, TAU);
    ctx.stroke();

    ctx.fillStyle = "rgba(255,255,255,.065)";
    ctx.font = "italic 900 92px 'Arial Narrow', Impact, sans-serif";
    ctx.textAlign = "center";
    ctx.textBaseline = "middle";
    ctx.fillText("OCTAGON", 0, -15);
    ctx.fillStyle = "rgba(255,47,56,.5)";
    ctx.font = "italic 900 82px 'Arial Narrow', Impact, sans-serif";
    ctx.fillText("RISE", 0, 67);
    ctx.restore();

    // Sponsor blocks around edge
    ctx.save();
    const sponsors = ["FIGHT NIGHT", "OR ATHLETICS", "LAS VEGAS", "RISE UP", "MAIN EVENT", "CHAMPIONSHIP"];
    ctx.textAlign = "center";
    for (let i = 0; i < sponsors.length; i++) {
      const a = OCT_ANGLE + (i * TAU) / 6;
      const x = 512 + Math.cos(a) * 345;
      const y = 512 + Math.sin(a) * 345;
      ctx.save();
      ctx.translate(x, y);
      ctx.rotate(a + Math.PI / 2);
      ctx.fillStyle = "rgba(255,255,255,.09)";
      ctx.font = "700 20px 'Arial Narrow', Arial, sans-serif";
      ctx.fillText(sponsors[i], 0, 0);
      ctx.fillStyle = "rgba(255,47,56,.35)";
      ctx.fillRect(-54, 14, 108, 2);
      ctx.restore();
    }
    ctx.restore();

    // Outer octagon line
    ctx.strokeStyle = "rgba(255,255,255,.075)";
    ctx.lineWidth = 4;
    ctx.beginPath();
    for (let i = 0; i <= 8; i++) {
      const a = OCT_ANGLE + (i * TAU) / 8;
      const x = 512 + Math.cos(a) * 490;
      const y = 512 + Math.sin(a) * 490;
      if (i === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    }
    ctx.stroke();

    return makeMatTexture(canvas);
  }

  _platform() {
    const platform = new THREE.Mesh(
      new THREE.CylinderGeometry(5.75, 6.05, 0.62, 8, 1, false),
      this.matBlack,
    );
    platform.rotation.y = OCT_ANGLE;
    platform.position.y = 0.24;
    platform.receiveShadow = true;
    this.group.add(platform);

    const skirtMat = new THREE.MeshStandardMaterial({ color: 0x07080b, roughness: 0.6, metalness: 0.4 });
    const skirt = new THREE.Mesh(new THREE.CylinderGeometry(5.8, 5.98, 0.36, 8, 1, true), skirtMat);
    skirt.rotation.y = OCT_ANGLE;
    skirt.position.y = 0.06;
    this.group.add(skirt);

    const floorMat = new THREE.MeshStandardMaterial({
      map: this._floorTexture(),
      roughness: 0.9,
      metalness: 0.05,
      color: 0xffffff,
    });
    const floor = new THREE.Mesh(new THREE.CircleGeometry(5.55, 8), floorMat);
    floor.rotation.x = -Math.PI / 2;
    floor.rotation.z = OCT_ANGLE;
    floor.position.y = 0.56;
    floor.receiveShadow = true;
    this.group.add(floor);

    // Padded apron around the mat
    const verts = [];
    for (let i = 0; i < 8; i++) {
      const a = OCT_ANGLE + (i * TAU) / 8;
      verts.push(new THREE.Vector3(Math.cos(a) * 5.62, 0.58, Math.sin(a) * 5.62));
    }
    for (let i = 0; i < 8; i++) {
      const a = verts[i];
      const b = verts[(i + 1) % 8];
      const len = a.distanceTo(b);
      const pad = new THREE.Mesh(new THREE.BoxGeometry(len + 0.08, 0.14, 0.42), this.matPad);
      pad.position.copy(a).add(b).multiplyScalar(0.5);
      pad.position.y = 0.57;
      pad.rotation.y = Math.atan2(b.z - a.z, b.x - a.x);
      pad.castShadow = true;
      pad.receiveShadow = true;
      this.group.add(pad);

      const stripe = new THREE.Mesh(
        new THREE.BoxGeometry(len + 0.08, 0.025, 0.43),
        i % 2 === 0 ? this.matRedPad : this.matBluePad,
      );
      stripe.position.copy(pad.position);
      stripe.position.y = 0.647;
      stripe.rotation.y = pad.rotation.y;
      this.group.add(stripe);
    }

    // LED underglow
    const glowGeo = new THREE.CylinderGeometry(6.12, 6.12, 0.03, 8, 1, true);
    const glowMat = new THREE.MeshBasicMaterial({ color: 0xff2433, transparent: true, opacity: 0.5, side: THREE.DoubleSide });
    const glow = new THREE.Mesh(glowGeo, glowMat);
    glow.rotation.y = OCT_ANGLE;
    glow.position.y = 0.03;
    this.group.add(glow);
  }

  _cage() {
    const radius = 5.5;
    const bottom = 0.66;
    const height = 2.16;
    const top = bottom + height;
    const verts = [];
    for (let i = 0; i < 8; i++) {
      const a = OCT_ANGLE + (i * TAU) / 8;
      verts.push(new THREE.Vector3(Math.cos(a) * radius, 0, Math.sin(a) * radius));
    }

    const chainCanvas = makeCanvas(64);
    const cctx = chainCanvas.getContext("2d");
    cctx.fillStyle = "#000";
    cctx.fillRect(0, 0, 64, 64);
    cctx.strokeStyle = "#fff";
    cctx.lineWidth = 2.2;
    cctx.beginPath();
    cctx.moveTo(-4, 32);
    cctx.lineTo(32, -4);
    cctx.lineTo(68, 32);
    cctx.lineTo(32, 68);
    cctx.closePath();
    cctx.moveTo(32, -4);
    cctx.lineTo(32, 68);
    cctx.moveTo(-4, 32);
    cctx.lineTo(68, 32);
    cctx.stroke();

    for (let i = 0; i < 8; i++) {
      const a = verts[i];
      const b = verts[(i + 1) % 8];
      const len = a.distanceTo(b);
      const mid = a.clone().add(b).multiplyScalar(0.5);
      const angle = Math.atan2(b.z - a.z, b.x - a.x);

      const tex = new THREE.CanvasTexture(chainCanvas);
      tex.wrapS = tex.wrapT = THREE.RepeatWrapping;
      tex.repeat.set(Math.max(2, Math.round(len / 0.38)), Math.round(height / 0.38));
      tex.colorSpace = THREE.SRGBColorSpace;
      const meshMat = new THREE.MeshStandardMaterial({
        color: 0x535963,
        map: tex,
        alphaMap: tex,
        transparent: true,
        alphaTest: 0.18,
        side: THREE.DoubleSide,
        metalness: 0.9,
        roughness: 0.42,
        depthWrite: false,
      });
      const panel = new THREE.Mesh(new THREE.PlaneGeometry(len, height), meshMat);
      panel.position.set(mid.x, bottom + height / 2, mid.z);
      panel.rotation.y = -angle;
      panel.renderOrder = 2;
      this.group.add(panel);

      // Top + bottom rails
      for (const y of [bottom, top]) {
        const rail = new THREE.Mesh(new THREE.CylinderGeometry(0.055, 0.055, len, 8), this.matSteel);
        rail.position.set(mid.x, y, mid.z);
        rail.rotation.z = Math.PI / 2;
        rail.rotation.y = -angle;
        this.group.add(rail);
      }

      // Padded top rail
      const pad = new THREE.Mesh(new THREE.CylinderGeometry(0.075, 0.075, len, 8), this.matRedPad);
      pad.position.set(mid.x, top + 0.06, mid.z);
      pad.rotation.z = Math.PI / 2;
      pad.rotation.y = -angle;
      this.group.add(pad);
    }

    // Posts and pads
    for (let i = 0; i < 8; i++) {
      const a = verts[i];
      const post = new THREE.Mesh(new THREE.CylinderGeometry(0.105, 0.125, 2.85, 10), this.matSteel);
      post.position.set(a.x, 1.9, a.z);
      post.castShadow = true;
      this.group.add(post);

      const pad = new THREE.Mesh(new THREE.CylinderGeometry(0.17, 0.19, 1.05, 8), this.matPad);
      pad.position.set(a.x, 1.22, a.z);
      this.group.add(pad);

      const cap = new THREE.Mesh(new THREE.SphereGeometry(0.13, 8, 6), this.matRedPad);
      cap.position.set(a.x, 3.32, a.z);
      this.group.add(cap);

      const light = new THREE.Mesh(
        new THREE.CylinderGeometry(0.035, 0.035, 0.5, 6),
        new THREE.MeshBasicMaterial({ color: 0xff2c37 }),
      );
      light.position.set(a.x, 2.73, a.z);
      this.group.add(light);
    }

    // Corner sponsor pads (red/blue alternating)
    const padPositions = [
      [-3.9, -3.9],
      [3.9, -3.9],
      [5.1, 0],
      [3.9, 3.9],
      [-3.9, 3.9],
      [-5.1, 0],
    ];
    padPositions.slice(0, 4).forEach(([x, z], i) => {
      const mat = i % 2 === 0 ? this.matRedPad : this.matBluePad;
      const banner = new THREE.Mesh(new THREE.BoxGeometry(0.95, 0.58, 0.08), mat);
      banner.position.set(x * 1.02, 1.66, z * 1.02);
      banner.lookAt(0, 1.66, 0);
      this.group.add(banner);
    });
  }

  _outside() {
    // Arena floor / walkway
    const arenaFloor = new THREE.Mesh(
      new THREE.CircleGeometry(24, 64),
      new THREE.MeshStandardMaterial({ color: 0x08090c, roughness: 0.95, metalness: 0.02 }),
    );
    arenaFloor.rotation.x = -Math.PI / 2;
    arenaFloor.position.y = -0.04;
    arenaFloor.receiveShadow = true;
    this.group.add(arenaFloor);

    // Low barrier ring
    const barrier = new THREE.Mesh(
      new THREE.CylinderGeometry(7.25, 7.25, 1.08, 64, 1, true),
      new THREE.MeshStandardMaterial({ color: 0x0b0d12, roughness: 0.92, side: THREE.DoubleSide }),
    );
    barrier.position.y = 0.5;
    this.group.add(barrier);

    const ledMat = new THREE.MeshBasicMaterial({ color: 0xff2f38, transparent: true, opacity: 0.75 });
    const led = new THREE.Mesh(new THREE.CylinderGeometry(7.27, 7.27, 0.045, 64, 1, true), ledMat);
    led.position.y = 0.98;
    this.group.add(led);

    // Camera / production platforms
    for (let i = 0; i < 4; i++) {
      const a = Math.PI / 4 + i * (Math.PI / 2);
      const platform = new THREE.Group();
      const base = new THREE.Mesh(new THREE.BoxGeometry(1.5, 0.35, 0.85), this.matBlack);
      base.position.y = 0.18;
      platform.add(base);
      const rail = new THREE.Mesh(new THREE.BoxGeometry(1.5, 0.04, 0.04), this.matSteel);
      rail.position.set(0, 0.88, -0.38);
      platform.add(rail);
      platform.position.set(Math.cos(a) * 6.6, 0, Math.sin(a) * 6.6);
      platform.rotation.y = -a;
      this.group.add(platform);
    }

    // LED ribbon above crowd
    const ribbonCanvas = makeCanvas(1024);
    const rctx = ribbonCanvas.getContext("2d");
    rctx.fillStyle = "#08090c";
    rctx.fillRect(0, 0, 1024, 128);
    rctx.fillStyle = "rgba(255,255,255,.86)";
    rctx.font = "800 54px 'Arial Narrow', Arial, sans-serif";
    rctx.textAlign = "center";
    rctx.textBaseline = "middle";
    for (let i = 0; i < 4; i++) {
      rctx.fillStyle = i % 2 === 0 ? "rgba(255,255,255,.7)" : "rgba(255,47,56,.8)";
      rctx.fillText("OCTAGON RISE", 128 + i * 256, 66);
    }
    const ribbonTex = new THREE.CanvasTexture(ribbonCanvas);
    ribbonTex.wrapS = THREE.RepeatWrapping;
    ribbonTex.repeat.set(3, 1);
    ribbonTex.colorSpace = THREE.SRGBColorSpace;
    const ribbon = new THREE.Mesh(
      new THREE.CylinderGeometry(13.4, 13.4, 1.2, 64, 1, true),
      new THREE.MeshBasicMaterial({ map: ribbonTex, side: THREE.BackSide, transparent: true, opacity: 0.86 }),
    );
    ribbon.position.y = 4.9;
    this.group.add(ribbon);
  }

  _crowd() {
    const bodyGeo = new THREE.CapsuleGeometry(0.11, 0.28, 3, 6);
    const headGeo = new THREE.SphereGeometry(0.088, 7, 5);
    const bodyMat = new THREE.MeshStandardMaterial({ roughness: 0.95, metalness: 0 });
    const headMat = new THREE.MeshStandardMaterial({ roughness: 0.92, metalness: 0 });

    const rows = 8;
    const perRow = 190;
    const total = rows * perRow;
    const bodies = new THREE.InstancedMesh(bodyGeo, bodyMat, total);
    const heads = new THREE.InstancedMesh(headGeo, headMat, total);
    bodies.instanceMatrix.setUsage(THREE.StaticDrawUsage);
    heads.instanceMatrix.setUsage(THREE.StaticDrawUsage);

    const dummy = new THREE.Object3D();
    const color = new THREE.Color();
    const shirtColors = [
      0x222a38, 0x3c1f26, 0x1e2a26, 0x332c24, 0x252028, 0x1a2028, 0x3a2e1f,
      0x46252b, 0x223246, 0x2a2a2a, 0x5a2930, 0x21323a, 0x3b3444, 0x4b3a28,
    ];
    const skins = [0xc38a63, 0x8b5a3c, 0x5f3b2a, 0xe0ad84, 0x9a6a4a, 0x764c35];

    let index = 0;
    for (let row = 0; row < rows; row++) {
      const radius = 8.25 + row * 0.74;
      const yBase = 0.86 + row * 0.43;
      for (let i = 0; i < perRow; i++) {
        const angle = (i / perRow) * TAU + row * 0.055 + (Math.random() - 0.5) * 0.018;
        const crowdX = Math.cos(angle) * radius + (Math.random() - 0.5) * 0.18;
        const crowdZ = Math.sin(angle) * radius + (Math.random() - 0.5) * 0.18;
        const scale = 0.82 + Math.random() * 0.35;
        dummy.position.set(crowdX, yBase + Math.random() * 0.1, crowdZ);
        dummy.rotation.y = -angle + Math.PI;
        dummy.scale.setScalar(scale);
        dummy.updateMatrix();
        bodies.setMatrixAt(index, dummy.matrix);
        color.setHex(shirtColors[(Math.random() * shirtColors.length) | 0]);
        color.multiplyScalar(0.55 + Math.random() * 0.35);
        bodies.setColorAt(index, color);

        dummy.position.y += 0.27 * scale;
        dummy.scale.setScalar(scale);
        dummy.updateMatrix();
        heads.setMatrixAt(index, dummy.matrix);
        color.setHex(skins[(Math.random() * skins.length) | 0]).multiplyScalar(0.55 + Math.random() * 0.3);
        heads.setColorAt(index, color);
        index++;
      }
    }
    bodies.instanceColor.needsUpdate = true;
    heads.instanceColor.needsUpdate = true;
    this.group.add(bodies, heads);

    // Tiny camera flashes in the crowd
    const flashMat = new THREE.MeshBasicMaterial({ color: 0xf7f4e8, transparent: true, opacity: 0 });
    const flashGeo = new THREE.PlaneGeometry(0.055, 0.055);
    for (let i = 0; i < 34; i++) {
      const flash = new THREE.Mesh(flashGeo, flashMat.clone());
      const angle = Math.random() * TAU;
      const radius = 8.2 + Math.random() * 5.2;
      flash.position.set(Math.cos(angle) * radius, 1 + Math.random() * 2.4, Math.sin(angle) * radius);
      flash.lookAt(0, 2, 0);
      flash.userData = {
        phase: Math.random() * TAU,
        speed: 0.5 + Math.random() * 1.8,
        max: 0.55 + Math.random() * 0.45,
      };
      this.flashes.push(flash);
      this.group.add(flash);
    }

    // Smoke / dust points
    const dustGeo = new THREE.BufferGeometry();
    const count = 240;
    const positions = new Float32Array(count * 3);
    for (let i = 0; i < count; i++) {
      const angle = Math.random() * TAU;
      const radius = Math.random() * 7.5;
      positions[i * 3] = Math.cos(angle) * radius;
      positions[i * 3 + 1] = 0.6 + Math.random() * 6;
      positions[i * 3 + 2] = Math.sin(angle) * radius;
    }
    dustGeo.setAttribute("position", new THREE.BufferAttribute(positions, 3));
    const dust = new THREE.Points(
      dustGeo,
      new THREE.PointsMaterial({
        color: 0xffe6c2,
        size: 0.022,
        transparent: true,
        opacity: 0.26,
        depthWrite: false,
        blending: THREE.AdditiveBlending,
      }),
    );
    this.dust = dust;
    this.group.add(dust);
  }

  _jumbotron() {
    const beamMat = this.matSteel;
    for (let i = -1; i <= 1; i += 2) {
      const cable = new THREE.Mesh(new THREE.CylinderGeometry(0.018, 0.018, 5.0, 5), beamMat);
      cable.position.set(i * 2.35, 9.3, -9.6);
      this.group.add(cable);
    }

    const housing = new THREE.Mesh(new THREE.BoxGeometry(7.4, 3.85, 0.38), this.matBlack);
    housing.position.set(0, 7.0, -9.6);
    this.group.add(housing);

    const glowFrame = new THREE.Mesh(
      new THREE.BoxGeometry(7.62, 4.05, 0.2),
      new THREE.MeshBasicMaterial({ color: 0x251014, transparent: true, opacity: 0.8 }),
    );
    glowFrame.position.set(0, 7.0, -9.82);
    this.group.add(glowFrame);

    this.screenCanvas = makeCanvas(1024);
    this.screenCanvas.height = 512;
    this.screenTexture = new THREE.CanvasTexture(this.screenCanvas);
    this.screenTexture.colorSpace = THREE.SRGBColorSpace;
    this.screenTexture.anisotropy = 8;
    this.screen = new THREE.Mesh(
      new THREE.PlaneGeometry(7.1, 3.55),
      new THREE.MeshBasicMaterial({ map: this.screenTexture, toneMapped: false }),
    );
    this.screen.position.set(0, 7.0, -9.78);
    this.group.add(this.screen);

    this._drawScreen();

    // Overhead truss
    const trussMat = this.matSteel;
    for (let i = -1; i <= 1; i += 2) {
      const beam = new THREE.Mesh(new THREE.CylinderGeometry(0.08, 0.08, 18, 8), trussMat);
      beam.rotation.z = Math.PI / 2;
      beam.position.set(0, 11.2, i * 4.4);
      this.group.add(beam);
    }
    for (let i = -3; i <= 3; i++) {
      const beam = new THREE.Mesh(new THREE.CylinderGeometry(0.05, 0.05, 8.8, 6), trussMat);
      beam.rotation.x = Math.PI / 2;
      beam.position.set(i * 2.8, 11.2, 0);
      this.group.add(beam);
    }
  }

  _drawScreen() {
    const ctx = this.screenCanvas.getContext("2d");
    const { width, height } = this.screenCanvas;
    const g = ctx.createLinearGradient(0, 0, width, height);
    g.addColorStop(0, "#17191f");
    g.addColorStop(0.55, "#0b0c10");
    g.addColorStop(1, "#2b0a0f");
    ctx.fillStyle = g;
    ctx.fillRect(0, 0, width, height);
    ctx.strokeStyle = "rgba(255,47,56,.55)";
    ctx.lineWidth = 5;
    ctx.strokeRect(16, 16, width - 32, height - 32);

    ctx.textAlign = "center";
    ctx.fillStyle = "rgba(255,255,255,.85)";
    ctx.font = "800 26px 'Arial Narrow', Arial, sans-serif";
    ctx.letterSpacing = "10px";
    ctx.fillText("OCTAGON RISE", width / 2, 74);
    ctx.fillStyle = "rgba(255,47,56,.85)";
    ctx.fillRect(width / 2 - 90, 91, 180, 3);

    ctx.fillStyle = "rgba(255,255,255,.92)";
    ctx.font = "900 78px 'Arial Narrow', Impact, sans-serif";
    ctx.fillText(this.screenText.left, width / 2 - 214, 205);
    ctx.fillStyle = "rgba(255,47,56,.95)";
    ctx.font = "italic 900 62px 'Arial Narrow', Impact, sans-serif";
    ctx.fillText("VS", width / 2, 203);
    ctx.fillStyle = "rgba(255,255,255,.92)";
    ctx.fillText(this.screenText.right, width / 2 + 214, 205);

    ctx.fillStyle = "rgba(255,255,255,.45)";
    ctx.font = "700 21px 'Arial Narrow', Arial, sans-serif";
    ctx.fillText("FIGHT NIGHT 07  ·  LAS VEGAS  ·  MAIN EVENT", width / 2, 283);

    ctx.fillStyle = "#ff2f38";
    ctx.fillRect(width / 2 - 125, 330, 250, 45);
    ctx.fillStyle = "#fff";
    ctx.font = "800 23px 'Arial Narrow', Arial, sans-serif";
    ctx.fillText(this.screenText.round, width / 2, 360);

    // scanlines
    ctx.fillStyle = "rgba(0,0,0,.08)";
    for (let y = 0; y < height; y += 3) ctx.fillRect(0, y, width, 1);
    this.screenTexture.needsUpdate = true;
  }

  setScreen({ left, right, round }) {
    if (left) this.screenText.left = left;
    if (right) this.screenText.right = right;
    if (round) this.screenText.round = round;
    this._drawScreen();
  }

  _lights() {
    const hemi = new THREE.HemisphereLight(0x9aabc4, 0x080604, 0.58);
    this.group.add(hemi);

    const key = new THREE.SpotLight(0xfff0da, 1550, 30, 0.55, 0.65, 1.35);
    key.position.set(1.4, 11.8, 5.2);
    key.target.position.set(0, 0.8, 0);
    key.castShadow = true;
    key.shadow.mapSize.set(1024, 1024);
    key.shadow.camera.near = 2;
    key.shadow.camera.far = 24;
    key.shadow.bias = -0.00013;
    key.shadow.normalBias = 0.02;
    this.group.add(key, key.target);

    const rimRed = new THREE.SpotLight(0xff2638, 640, 24, 0.48, 0.8, 1.5);
    rimRed.position.set(-8.5, 5.5, -5.0);
    rimRed.target.position.set(0, 1.2, 0);
    this.group.add(rimRed, rimRed.target);

    const rimBlue = new THREE.SpotLight(0x3c7cff, 620, 24, 0.48, 0.8, 1.5);
    rimBlue.position.set(8.5, 5.5, -4.2);
    rimBlue.target.position.set(0, 1.2, 0);
    this.group.add(rimBlue, rimBlue.target);

    const front = new THREE.PointLight(0xffd9b8, 63, 14, 1.8);
    front.position.set(0, 4.6, 7.5);
    this.group.add(front);

    // visible light shafts
    const shaftMat = new THREE.MeshBasicMaterial({
      color: 0xffdfb8,
      transparent: true,
      opacity: 0.017,
      side: THREE.DoubleSide,
      depthWrite: false,
      blending: THREE.AdditiveBlending,
    });
    for (const [x, z] of [
      [1.4, 5.2],
      [-5.7, -3.8],
      [5.7, -3.8],
    ]) {
      const shaft = new THREE.Mesh(new THREE.ConeGeometry(2.7, 11, 24, 1, true), shaftMat);
      shaft.position.set(x, 6.0, z);
      this.group.add(shaft);
    }

    // corner LED columns in the distance
    const red = new THREE.PointLight(0xff2033, 35, 12, 1.6);
    red.position.set(-8, 2, -7);
    this.group.add(red);
    const blue = new THREE.PointLight(0x2a67ff, 35, 12, 1.6);
    blue.position.set(8, 2, -7);
    this.group.add(blue);
  }

  _atmosphere() {
    // haze sprites around the cage
    const canvas = makeCanvas(256);
    const ctx = canvas.getContext("2d");
    const g = ctx.createRadialGradient(128, 128, 0, 128, 128, 128);
    g.addColorStop(0, "rgba(255,255,255,.16)");
    g.addColorStop(0.5, "rgba(255,255,255,.05)");
    g.addColorStop(1, "rgba(255,255,255,0)");
    ctx.fillStyle = g;
    ctx.fillRect(0, 0, 256, 256);
    const texture = new THREE.CanvasTexture(canvas);
    texture.colorSpace = THREE.SRGBColorSpace;
    const mat = new THREE.SpriteMaterial({
      map: texture,
      color: 0xffdfc0,
      transparent: true,
      opacity: 0.26,
      blending: THREE.AdditiveBlending,
      depthWrite: false,
    });
    for (let i = 0; i < 9; i++) {
      const sprite = new THREE.Sprite(mat.clone());
      const angle = (i / 9) * TAU;
      sprite.position.set(Math.cos(angle) * (2.5 + Math.random() * 3), 1.2 + Math.random() * 2.4, Math.sin(angle) * (2.5 + Math.random() * 3));
      sprite.scale.setScalar(2.4 + Math.random() * 2.2);
      sprite.userData.phase = Math.random() * TAU;
      this.group.add(sprite);
    }
  }

  _referee() {
    const ref = new THREE.Group();
    ref.name = "referee";
    const skin = new THREE.MeshStandardMaterial({ color: 0x8b5f43, roughness: 0.8 });
    const shirt = new THREE.MeshStandardMaterial({ color: 0x111318, roughness: 0.9 });
    const pants = new THREE.MeshStandardMaterial({ color: 0x1d2027, roughness: 0.92 });
    const shoe = new THREE.MeshStandardMaterial({ color: 0x08090b, roughness: 0.6 });

    const torso = new THREE.Mesh(new THREE.CapsuleGeometry(0.22, 0.38, 4, 8), shirt);
    torso.position.y = 1.12;
    torso.scale.set(1.22, 1, 0.74);
    torso.castShadow = true;
    ref.add(torso);
    const neck = new THREE.Mesh(new THREE.CylinderGeometry(0.09, 0.1, 0.14, 8), skin);
    neck.position.y = 1.47;
    ref.add(neck);
    const head = new THREE.Mesh(new THREE.CapsuleGeometry(0.14, 0.12, 4, 8), skin);
    head.position.y = 1.65;
    head.scale.set(0.92, 1.12, 0.95);
    head.castShadow = true;
    ref.add(head);
    const hair = new THREE.Mesh(new THREE.SphereGeometry(0.135, 8, 5, 0, TAU, 0, Math.PI * 0.48), new THREE.MeshStandardMaterial({ color: 0x0b0b0c, roughness: 1 }));
    hair.position.y = 1.71;
    ref.add(hair);

    for (const side of [-1, 1]) {
      const leg = new THREE.Mesh(new THREE.CapsuleGeometry(0.095, 0.58, 3, 6), pants);
      leg.position.set(side * 0.12, 0.46, 0);
      leg.castShadow = true;
      ref.add(leg);
      const foot = new THREE.Mesh(new THREE.BoxGeometry(0.16, 0.1, 0.28), shoe);
      foot.position.set(side * 0.12, 0.07, 0.06);
      ref.add(foot);
      const arm = new THREE.Mesh(new THREE.CapsuleGeometry(0.075, 0.38, 3, 6), skin);
      arm.position.set(side * 0.37, 1.03, 0.04);
      arm.rotation.z = side * 0.18;
      arm.castShadow = true;
      ref.add(arm);
    }
    ref.position.set(0.15, 0.56, -3.6);
    ref.rotation.y = 0.05;
    this.referee = ref;
    this.group.add(ref);
  }

  update(dt, elapsed) {
    this.time = elapsed;
    if (this.dust) {
      this.dust.rotation.y += dt * 0.007;
      const positions = this.dust.geometry.attributes.position;
      for (let i = 0; i < positions.count; i++) {
        const y = positions.getY(i) + Math.sin(elapsed * 0.4 + i) * dt * 0.012;
        positions.setY(i, y > 6.6 ? 0.7 : y);
      }
      positions.needsUpdate = true;
    }
    for (const flash of this.flashes) {
      const { phase, speed, max } = flash.userData;
      const cycle = (Math.sin(elapsed * speed * 1.7 + phase) + 1) * 0.5;
      const val = cycle > 0.94 ? (cycle - 0.94) * (max / 0.06) : 0;
      flash.material.opacity = Math.min(max, val);
      const s = 1 + val * 5;
      flash.scale.setScalar(s);
    }
    if (this.referee) {
      this.referee.rotation.y = 0.05 + Math.sin(elapsed * 0.32) * 0.08;
      this.referee.position.x = 0.15 + Math.sin(elapsed * 0.24) * 0.18;
    }
  }
}

import * as THREE from "three";
import { MOVES } from "./config.js";

const TAU = Math.PI * 2;

function damp(current, target, rate, dt) {
  return current + (target - current) * (1 - Math.exp(-rate * dt));
}

function shadowTexture() {
  const canvas = document.createElement("canvas");
  canvas.width = canvas.height = 128;
  const ctx = canvas.getContext("2d");
  const g = ctx.createRadialGradient(64, 64, 4, 64, 64, 62);
  g.addColorStop(0, "rgba(0,0,0,.55)");
  g.addColorStop(0.55, "rgba(0,0,0,.25)");
  g.addColorStop(1, "rgba(0,0,0,0)");
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, 128, 128);
  const texture = new THREE.CanvasTexture(canvas);
  texture.colorSpace = THREE.SRGBColorSpace;
  return texture;
}

function capsule(radius, length, material) {
  return new THREE.Mesh(new THREE.CapsuleGeometry(radius, length, 5, 10), material);
}

export class Fighter {
  constructor(config, side = "left") {
    this.config = config;
    this.side = side;
    this.root = new THREE.Group();
    this.root.name = `fighter-${config.id}-${side}`;
    this.visual = new THREE.Group();
    this.root.add(this.visual);

    this.baseY = 0;
    this.yaw = 0;
    this.action = null;
    this.blocking = false;
    this.downed = false;
    this.downTimer = 0;
    this.ko = false;
    this.hurtTimer = 0;
    this.celebrating = false;
    this.invulnerable = 0;
    this.walkPhase = Math.random() * TAU;
    this.locomotion = 0;
    this.alternateArm = side === "left" ? "l" : "r";
    this.pose = {};
    this.poseReady = false;
    this._build();
    this._initPose();
  }

  _initPose() {
    this.pose = {
      torsoX: 0.08,
      torsoY: 0,
      torsoZ: 0,
      headX: -0.03,
      headY: 0,
      headZ: 0,
      lArmX: -0.56,
      lArmY: 0.16,
      lArmZ: 0.2,
      lElbowX: -1.72,
      lElbowY: 0,
      lElbowZ: 0,
      rArmX: -0.56,
      rArmY: -0.16,
      rArmZ: -0.2,
      rElbowX: -1.72,
      rElbowY: 0,
      rElbowZ: 0,
      lHipX: -0.2,
      lHipY: -0.05,
      lHipZ: 0.045,
      lKneeX: 0.28,
      rHipX: 0.16,
      rHipY: 0.06,
      rHipZ: -0.045,
      rKneeX: 0.3,
      visualY: 0,
    };
    this.poseReady = true;
  }

  _build() {
    const c = this.config;
    const scale = c.id === "okafor" ? 1.075 : c.id === "tanaka" ? 0.958 : 1;
    this.visual.scale.setScalar(scale);

    const skin = new THREE.MeshStandardMaterial({ color: c.skin, roughness: 0.62, metalness: 0.02 });
    const skinShade = new THREE.MeshStandardMaterial({ color: c.skinShade, roughness: 0.7, metalness: 0 });
    const trunks = new THREE.MeshStandardMaterial({ color: c.trunks, roughness: 0.58, metalness: 0.08 });
    const trim = new THREE.MeshStandardMaterial({ color: c.trim, roughness: 0.74, metalness: 0.02 });
    const glove = new THREE.MeshStandardMaterial({ color: c.trunks, roughness: 0.56, metalness: 0.06 });
    const gloveTrim = new THREE.MeshStandardMaterial({ color: c.trim, roughness: 0.78, metalness: 0 });
    const hair = new THREE.MeshStandardMaterial({ color: c.hair, roughness: 0.92, metalness: 0 });
    const dark = new THREE.MeshStandardMaterial({ color: 0x0b0a0a, roughness: 0.5, metalness: 0.1 });
    const tape = new THREE.MeshStandardMaterial({ color: 0xe8e1d2, roughness: 0.94, metalness: 0 });
    const mouth = new THREE.MeshStandardMaterial({ color: 0xd54040, roughness: 0.6 });
    this.materials = { skin, skinShade, trunks, trim, glove, gloveTrim, hair, dark, tape, mouth };

    const add = (mesh, cast = true) => {
      mesh.castShadow = cast;
      mesh.receiveShadow = true;
      this.visual.add(mesh);
      return mesh;
    };

    // Contact shadow
    this.shadow = new THREE.Mesh(
      new THREE.PlaneGeometry(1.3, 1.3),
      new THREE.MeshBasicMaterial({
        map: shadowTexture(),
        transparent: true,
        opacity: 0.85,
        depthWrite: false,
      }),
    );
    this.shadow.rotation.x = -Math.PI / 2;
    this.shadow.position.y = 0.012;
    this.root.add(this.shadow);

    // Pelvis / trunks
    this.hips = new THREE.Group();
    this.hips.position.y = 0.98;
    this.visual.add(this.hips);

    const trunksMesh = new THREE.Mesh(new THREE.CylinderGeometry(0.225, 0.255, 0.36, 10, 1, false), trunks);
    trunksMesh.scale.z = 0.78;
    trunksMesh.position.y = 0.05;
    trunksMesh.castShadow = true;
    trunksMesh.receiveShadow = true;
    this.hips.add(trunksMesh);

    const waist = new THREE.Mesh(new THREE.CylinderGeometry(0.235, 0.235, 0.065, 12, 1, true), trim);
    waist.scale.z = 0.8;
    waist.position.y = 0.235;
    this.hips.add(waist);

    for (const side of [-1, 1]) {
      const stripe = new THREE.Mesh(new THREE.BoxGeometry(0.045, 0.33, 0.025), trim);
      stripe.position.set(side * 0.205, 0.02, 0.11);
      stripe.rotation.y = side * 0.2;
      this.hips.add(stripe);
    }

    // Torso pivot
    this.torso = new THREE.Group();
    this.torso.position.y = 1.12;
    this.visual.add(this.torso);

    const abdomen = new THREE.Mesh(new THREE.CapsuleGeometry(0.21, 0.2, 5, 10), skin);
    abdomen.position.y = 0.1;
    abdomen.scale.set(1.2, 1, 0.72);
    abdomen.castShadow = true;
    this.torso.add(abdomen);

    const chest = new THREE.Mesh(new THREE.CapsuleGeometry(0.3, 0.17, 5, 12), skin);
    chest.position.set(0, 0.36, -0.015);
    chest.scale.set(1.38, 1.08, 0.79);
    chest.castShadow = true;
    this.torso.add(chest);

    const traps = new THREE.Mesh(new THREE.CapsuleGeometry(0.15, 0.28, 4, 8), skin);
    traps.rotation.z = Math.PI / 2;
    traps.position.set(0, 0.55, -0.05);
    traps.scale.set(1, 1, 0.75);
    this.torso.add(traps);

    // Pecs
    for (const side of [-1, 1]) {
      const pec = new THREE.Mesh(new THREE.SphereGeometry(0.17, 10, 8), skinShade);
      pec.position.set(side * 0.15, 0.4, 0.155);
      pec.scale.set(1.1, 0.72, 0.34);
      this.torso.add(pec);

      const lat = new THREE.Mesh(new THREE.SphereGeometry(0.18, 8, 8), skin);
      lat.position.set(side * 0.3, 0.25, -0.08);
      lat.scale.set(0.5, 1.15, 0.5);
      this.torso.add(lat);

      const shoulder = new THREE.Mesh(new THREE.SphereGeometry(0.135, 10, 8), skin);
      shoulder.position.set(side * 0.43, 0.48, -0.01);
      shoulder.scale.set(1.15, 0.95, 1);
      shoulder.castShadow = true;
      this.torso.add(shoulder);
    }

    // Tattoo strokes for Moreno
    if (c.tattoos) {
      const tatMat = new THREE.MeshBasicMaterial({ color: 0x2a1712, transparent: true, opacity: 0.52, depthWrite: false });
      for (let i = 0; i < 3; i++) {
        const band = new THREE.Mesh(new THREE.TorusGeometry(0.185 + i * 0.015, 0.008, 4, 18, Math.PI * 0.9), tatMat);
        band.position.set(-0.12, 0.35 + i * 0.035, 0.21);
        band.rotation.z = 0.4;
        band.rotation.x = 0.14;
        band.scale.set(1, 0.55, 1);
        this.torso.add(band);
      }
      const slash = new THREE.Mesh(new THREE.BoxGeometry(0.018, 0.22, 0.005), tatMat);
      slash.position.set(0.235, 0.34, 0.19);
      slash.rotation.z = -0.42;
      this.torso.add(slash);
    }

    // Neck + head
    const neck = new THREE.Mesh(new THREE.CylinderGeometry(0.085, 0.105, 0.15, 9), skin);
    neck.position.y = 0.62;
    this.torso.add(neck);

    this.head = new THREE.Group();
    this.head.position.y = 0.79;
    this.torso.add(this.head);

    const skull = new THREE.Mesh(new THREE.SphereGeometry(0.16, 16, 12), skin);
    skull.scale.set(0.88, 1.12, 0.92);
    skull.position.y = 0.025;
    skull.castShadow = true;
    this.head.add(skull);

    const jaw = new THREE.Mesh(new THREE.SphereGeometry(0.12, 12, 8), skin);
    jaw.scale.set(0.92, 0.72, 0.95);
    jaw.position.set(0, -0.065, 0.035);
    jaw.castShadow = true;
    this.head.add(jaw);

    for (const side of [-1, 1]) {
      const ear = new THREE.Mesh(new THREE.SphereGeometry(0.035, 7, 5), skinShade);
      ear.position.set(side * 0.145, 0.015, 0);
      ear.scale.set(0.65, 1, 0.65);
      this.head.add(ear);

      const eye = new THREE.Mesh(new THREE.SphereGeometry(0.016, 7, 6), dark);
      eye.position.set(side * 0.058, 0.045, 0.143);
      this.head.add(eye);

      const brow = new THREE.Mesh(new THREE.BoxGeometry(0.058, 0.011, 0.012), hair);
      brow.position.set(side * 0.06, 0.078, 0.15);
      brow.rotation.z = side * 0.12;
      this.head.add(brow);
    }

    const nose = new THREE.Mesh(new THREE.ConeGeometry(0.034, 0.085, 6), skin);
    nose.rotation.x = Math.PI / 2;
    nose.position.set(0, 0.005, 0.165);
    nose.scale.set(1, 1, 0.8);
    this.head.add(nose);

    const mouth = new THREE.Mesh(new THREE.BoxGeometry(0.07, 0.014, 0.012), mouth);
    mouth.position.set(0, -0.058, 0.148);
    this.head.add(mouth);

    // Hair styles
    if (c.hairStyle === "fade") {
      const cap = new THREE.Mesh(new THREE.SphereGeometry(0.164, 12, 8, 0, TAU, 0, Math.PI * 0.52), hair);
      cap.position.y = 0.045;
      cap.scale.set(0.93, 1.05, 0.98);
      this.head.add(cap);
      const top = new THREE.Mesh(new THREE.BoxGeometry(0.18, 0.055, 0.1), hair);
      top.position.set(0, 0.175, -0.015);
      top.rotation.x = -0.12;
      this.head.add(top);
      for (const side of [-1, 1]) {
        const line = new THREE.Mesh(new THREE.BoxGeometry(0.012, 0.1, 0.01), dark);
        line.position.set(side * 0.14, 0.07, 0.02);
        this.head.add(line);
      }
    } else if (c.hairStyle === "undercut") {
      const cap = new THREE.Mesh(new THREE.SphereGeometry(0.166, 12, 8, 0, TAU, 0, Math.PI * 0.42), hair);
      cap.position.y = 0.062;
      cap.scale.set(0.95, 1.18, 1);
      this.head.add(cap);
      const fringe = new THREE.Mesh(new THREE.BoxGeometry(0.24, 0.055, 0.06), hair);
      fringe.position.set(0, 0.15, 0.1);
      fringe.rotation.x = 0.18;
      this.head.add(fringe);
    } else {
      const shine = new THREE.Mesh(new THREE.SphereGeometry(0.02, 6, 4), new THREE.MeshBasicMaterial({ color: 0xd8b08d, transparent: true, opacity: 0.18 }));
      shine.position.set(-0.04, 0.165, 0.02);
      this.head.add(shine);
    }

    if (c.id === "okafor") {
      const beard = new THREE.Mesh(new THREE.SphereGeometry(0.122, 10, 8), new THREE.MeshStandardMaterial({ color: 0x0b0908, roughness: 1, transparent: true, opacity: 0.92 }));
      beard.scale.set(0.96, 0.65, 0.95);
      beard.position.set(0, -0.085, 0.045);
      this.head.add(beard);
    }

    // Arms
    this.armL = this._buildArm(-1, skin, glove, gloveTrim, tape);
    this.armR = this._buildArm(1, skin, glove, gloveTrim, tape);
    this.armL.position.set(-0.43, 0.48, 0);
    this.armR.position.set(0.43, 0.48, 0);
    this.torso.add(this.armL, this.armR);

    // Legs
    this.legL = this._buildLeg(-1, skin, trunks, trim, tape);
    this.legR = this._buildLeg(1, skin, trunks, trim, tape);
    this.legL.position.set(-0.15, 0.98, 0);
    this.legR.position.set(0.15, 0.98, 0);
    this.visual.add(this.legL, this.legR);

    // Small corner marker on the back
    const tag = new THREE.Mesh(
      new THREE.BoxGeometry(0.16, 0.05, 0.012),
      new THREE.MeshBasicMaterial({ color: c.accent }),
    );
    tag.position.set(0, 0.27, -0.18);
    tag.rotation.x = -0.08;
    this.torso.add(tag);

    this.visual.traverse((node) => {
      if (node.isMesh) {
        node.castShadow = node.castShadow || node !== this.shadow;
        node.receiveShadow = true;
      }
    });
  }

  _buildArm(side, skin, glove, gloveTrim, tape) {
    const shoulder = new THREE.Group();
    const upper = capsule(0.075, 0.2, skin);
    upper.position.y = -0.175;
    upper.scale.set(1.02, 1, 1.02);
    upper.castShadow = true;
    shoulder.add(upper);

    const elbow = new THREE.Group();
    elbow.position.y = -0.34;
    shoulder.add(elbow);

    const forearm = capsule(0.058, 0.18, skin);
    forearm.position.y = -0.145;
    forearm.castShadow = true;
    elbow.add(forearm);

    const wrist = new THREE.Mesh(new THREE.CylinderGeometry(0.06, 0.065, 0.07, 8), gloveTrim);
    wrist.position.y = -0.285;
    elbow.add(wrist);

    const fist = new THREE.Mesh(new THREE.SphereGeometry(0.077, 12, 9), glove);
    fist.scale.set(0.95, 0.88, 1.12);
    fist.position.set(0, -0.33, 0.012);
    fist.castShadow = true;
    elbow.add(fist);

    const knuckle = new THREE.Mesh(new THREE.BoxGeometry(0.115, 0.025, 0.075), gloveTrim);
    knuckle.position.set(0, -0.364, 0.05);
    knuckle.rotation.x = 0.1;
    elbow.add(knuckle);

    const thumb = new THREE.Mesh(new THREE.CapsuleGeometry(0.024, 0.04, 3, 6), glove);
    thumb.position.set(side * -0.065, -0.332, 0.04);
    thumb.rotation.z = side * 0.55;
    elbow.add(thumb);

    // sponsor stripe on the forearm
    const band = new THREE.Mesh(new THREE.CylinderGeometry(0.063, 0.063, 0.026, 8), tape);
    band.position.y = -0.235;
    elbow.add(band);

    return shoulder;
  }

  _buildLeg(side, skin, trunks, trim, tape) {
    const hip = new THREE.Group();

    const thigh = capsule(0.108, 0.22, skin);
    thigh.position.y = -0.23;
    thigh.scale.set(1.04, 1, 1.04);
    thigh.castShadow = true;
    hip.add(thigh);

    // trunks leg
    const shortLeg = new THREE.Mesh(new THREE.CylinderGeometry(0.13, 0.14, 0.19, 8, 1, false), trunks);
    shortLeg.position.y = -0.045;
    shortLeg.scale.z = 0.92;
    shortLeg.castShadow = true;
    hip.add(shortLeg);

    const hem = new THREE.Mesh(new THREE.CylinderGeometry(0.141, 0.141, 0.022, 8, 1, true), trim);
    hem.position.y = -0.142;
    hem.scale.z = 0.92;
    hip.add(hem);

    const knee = new THREE.Group();
    knee.position.y = -0.47;
    hip.add(knee);

    const kneecap = new THREE.Mesh(new THREE.SphereGeometry(0.082, 8, 6), skin);
    kneecap.scale.set(1, 0.85, 1);
    knee.add(kneecap);

    const calf = capsule(0.078, 0.19, skin);
    calf.position.y = -0.19;
    calf.castShadow = true;
    knee.add(calf);

    const ankle = new THREE.Mesh(new THREE.CylinderGeometry(0.065, 0.074, 0.08, 8), tape);
    ankle.position.y = -0.34;
    knee.add(ankle);

    const foot = new THREE.Mesh(new THREE.BoxGeometry(0.13, 0.09, 0.26), new THREE.MeshStandardMaterial({ color: 0x15171c, roughness: 0.6, metalness: 0.25 }));
    foot.position.set(0, -0.41, 0.055);
    foot.castShadow = true;
    knee.add(foot);

    return { hip, knee };
  }

  playMove(key) {
    const move = MOVES[key];
    if (!move || this.action || this.blocking || this.downed || this.ko) return false;
    this.action = {
      key,
      move,
      t: 0,
      arm: key === "jab" || key === "heavy" ? this.alternateArm : "l",
      hitConsumed: false,
    };
    if (key === "jab") this.alternateArm = this.alternateArm === "l" ? "r" : "l";
    if (key === "heavy") this.alternateArm = this.alternateArm === "l" ? "r" : "l";
    return true;
  }

  cancelAction() {
    this.action = null;
  }

  setBlocking(value) {
    if (this.ko || this.downed) this.blocking = false;
    else this.blocking = value;
  }

  isAttacking() {
    return !!this.action;
  }

  isInWindup() {
    return !!this.action && this.action.t < this.action.move.windup;
  }

  hitLanded() {
    if (!this.action || this.action.hitConsumed) return false;
    if (this.action.t < this.action.move.hitAt) return false;
    this.action.hitConsumed = true;
    return true;
  }

  takeHit(heavy = false) {
    this.hurtTimer = heavy ? 0.5 : 0.32;
    this.blocking = false;
    if (this.action) this.cancelAction();
    if (this.downed) return;
  }

  knockDown(duration = 2.0) {
    this.cancelAction();
    this.blocking = false;
    this.downed = true;
    this.downTimer = duration;
    this.hurtTimer = 0;
  }

  setKO() {
    this.cancelAction();
    this.blocking = false;
    this.ko = true;
    this.downed = true;
    this.downTimer = 0;
    this.hurtTimer = 0;
  }

  setVictory(value) {
    this.celebrating = value;
    if (value) {
      this.action = null;
      this.blocking = false;
    }
  }

  reset() {
    this.action = null;
    this.blocking = false;
    this.downed = false;
    this.downTimer = 0;
    this.ko = false;
    this.hurtTimer = 0;
    this.celebrating = false;
    this.invulnerable = 0;
    this.locomotion = 0;
    this.visual.rotation.x = 0;
    this.visual.position.set(0, 0, 0);
    this._initPose();
  }

  setBaseY(y) {
    this.baseY = y;
    this.root.position.y = y;
  }

  setFacing(dx, dz, dt = 0.2) {
    const target = Math.atan2(dx, dz);
    let diff = ((target - this.yaw + Math.PI * 3) % TAU) - Math.PI;
    this.yaw += diff * (1 - Math.exp(-12 * dt));
    this.root.rotation.y = this.yaw;
  }

  update(dt, time, locomotion = 0) {
    this.locomotion = locomotion;
    if (this.invulnerable > 0) this.invulnerable -= dt;
    if (this.hurtTimer > 0) this.hurtTimer -= dt;

    if (this.downed && !this.ko) {
      this.downTimer -= dt;
      if (this.downTimer <= 0) {
        this.downed = false;
        this.invulnerable = 0.5;
      }
    }

    if (this.action) {
      this.action.t += dt;
      if (this.action.t >= this.action.move.duration) this.action = null;
    }

    const walking = Math.min(1, locomotion);
    this.walkPhase += dt * (2.3 + walking * 6.2);
    const bob = Math.sin(this.walkPhase * 2) * 0.008 * walking + Math.sin(time * 2.2 + (this.side === "left" ? 0 : 1.2)) * 0.008;

    const target = this._targetPose(time, walking);
    let rate = 11;
    if (this.action) rate = this.action.t < this.action.move.hitAt ? 24 : 16;
    if (this.downed || this.ko) rate = 7;
    this._blendPose(target, rate, dt);
    this._applyPose(bob, dt);

    // Falling / getting up is on the visual wrapper, so gameplay positions stay stable.
    const fallTarget = this.ko ? -Math.PI / 2.02 : this.downed ? -Math.PI / 2.15 : 0;
    this.visual.rotation.x = damp(this.visual.rotation.x, fallTarget, this.ko ? 4.2 : this.downed ? 7.2 : 8.5, dt);
    const fallY = this.ko || this.downed ? 0.1 : 0;
    this.visual.position.y = damp(this.visual.position.y, fallY + this.pose.visualY, 8, dt);
    this.visual.position.z = damp(this.visual.position.z, this.ko || this.downed ? -0.18 : 0, 7, dt);
    this.shadow.material.opacity = this.ko || this.downed ? 0.55 : 0.85;
  }

  _targetPose(time, walking) {
    const t = {
      torsoX: 0.08 + Math.sin(time * 2.2) * 0.012,
      torsoY: 0,
      torsoZ: 0,
      headX: -0.03,
      headY: Math.sin(time * 1.5) * 0.02,
      headZ: 0,
      lArmX: -0.56,
      lArmY: 0.16,
      lArmZ: 0.2,
      lElbowX: -1.72,
      lElbowY: 0,
      lElbowZ: 0,
      rArmX: -0.56,
      rArmY: -0.16,
      rArmZ: -0.2,
      rElbowX: -1.72,
      rElbowY: 0,
      rElbowZ: 0,
      lHipX: -0.2,
      lHipY: -0.05,
      lHipZ: 0.045,
      lKneeX: 0.28,
      rHipX: 0.16,
      rHipY: 0.06,
      rHipZ: -0.045,
      rKneeX: 0.3,
      visualY: 0,
    };

    // head bob / breathing
    t.headY += Math.sin(time * 2.6) * 0.032;

    const shuffle = Math.sin(this.walkPhase) * 0.055 * walking;
    t.lHipX += shuffle;
    t.rHipX -= shuffle;
    t.lKneeX += Math.abs(shuffle) * 0.5;
    t.rKneeX += Math.abs(shuffle) * 0.5;
    t.torsoY += Math.sin(this.walkPhase) * 0.04 * walking;

    if (this.celebrating) {
      return {
        ...t,
        torsoX: -0.06,
        torsoY: Math.sin(time * 2.4) * 0.12,
        headX: -0.14,
        lArmX: -2.76,
        lArmY: -0.05,
        lArmZ: 0.5,
        lElbowX: -0.08,
        rArmX: -2.76,
        rArmY: 0.05,
        rArmZ: -0.5,
        rElbowX: -0.08,
        lHipX: -0.13,
        rHipX: 0.13,
        visualY: Math.abs(Math.sin(time * 4.2)) * 0.035,
      };
    }

    if (this.ko) {
      return {
        ...t,
        torsoX: -0.05,
        headX: -0.2,
        headY: 0.3,
        lArmX: -0.25,
        lArmZ: 0.55,
        lElbowX: -0.4,
        rArmX: -0.25,
        rArmZ: -0.55,
        rElbowX: -0.4,
        lHipX: -0.05,
        rHipX: 0.08,
        lKneeX: 0.35,
        rKneeX: 0.2,
      };
    }

    if (this.downed) {
      return {
        ...t,
        torsoX: 0.05,
        headX: 0.18,
        lArmX: -0.3,
        lArmZ: 0.4,
        lElbowX: -0.6,
        rArmX: -0.35,
        rArmZ: -0.45,
        rElbowX: -0.55,
        lHipX: -0.15,
        rHipX: 0.2,
        lKneeX: 0.3,
        rKneeX: 0.3,
      };
    }

    if (this.hurtTimer > 0) {
      const hurt = Math.min(1, this.hurtTimer * 3.5);
      return {
        ...t,
        torsoX: t.torsoX - 0.18 * hurt,
        torsoY: 0.15 * hurt,
        headX: -0.32 * hurt,
        headY: 0.18 * hurt,
        lArmX: -0.3,
        lArmZ: 0.4,
        lElbowX: -1.1,
        rArmX: -0.36,
        rArmZ: -0.48,
        rElbowX: -1.0,
        lHipX: -0.32,
        rHipX: 0.28,
      };
    }

    if (this.blocking) {
      return {
        ...t,
        torsoX: 0.17,
        headX: 0.13,
        lArmX: -1.48,
        lArmY: 0.2,
        lArmZ: 0.45,
        lElbowX: -2.05,
        lElbowZ: 0.12,
        rArmX: -1.48,
        rArmY: -0.2,
        rArmZ: -0.45,
        rElbowX: -2.05,
        rElbowZ: -0.12,
        lHipX: -0.3,
        rHipX: 0.24,
        lKneeX: 0.45,
        rKneeX: 0.42,
      };
    }

    if (this.action) {
      const { key, t: at, arm, move } = this.action;
      const p = Math.min(1, at / move.duration);
      const wind = Math.min(1, at / Math.max(0.01, move.hitAt));
      const retract = Math.max(0, (at - move.hitAt) / Math.max(0.01, move.duration - move.hitAt));
      const extension = at < move.hitAt ? Math.sin(wind * Math.PI * 0.5) * 0.3 : Math.cos(retract * Math.PI * 0.5);
      const twist = (arm === "l" ? 1 : -1) * extension * 0.2;

      if (key === "jab") {
        const shoulder = arm === "l" ? "l" : "r";
        const other = shoulder === "l" ? "r" : "l";
        t.torsoY = twist;
        t.headY = -twist * 0.35;
        t[`${shoulder}ArmX`] = -0.56 - extension * 1.08;
        t[`${shoulder}ArmZ`] = (shoulder === "l" ? 0.2 : -0.2) - extension * (shoulder === "l" ? 0.14 : -0.14);
        t[`${shoulder}ElbowX`] = -1.72 + extension * 1.62;
        t[`${other}ArmX`] = -0.58;
        t.lHipX = -0.24;
        t.rHipX = 0.18;
      } else if (key === "heavy") {
        const shoulder = arm === "l" ? "l" : "r";
        const other = shoulder === "l" ? "r" : "l";
        t.torsoY = twist * 1.3;
        t.torsoX = 0.12 + extension * 0.12;
        t.headY = -twist;
        t[`${shoulder}ArmX`] = -0.56 - extension * 0.86;
        t[`${shoulder}ArmY`] = (shoulder === "l" ? 0.16 : -0.16) * (1 - extension);
        t[`${shoulder}ArmZ`] = (shoulder === "l" ? 0.2 : -0.2) + extension * (shoulder === "l" ? 0.18 : -0.18);
        t[`${shoulder}ElbowX`] = -1.72 + extension * 1.38;
        t[`${other}ArmX`] = -0.48;
        t[`${other}ElbowX`] = -1.9;
        t.lHipX = -0.32;
        t.rHipX = 0.26;
        t.lKneeX = 0.38;
      } else if (key === "kick") {
        const extensionKick = at < move.hitAt ? Math.sin(wind * Math.PI * 0.5) : Math.cos(retract * Math.PI * 0.42);
        t.torsoX = -0.2 - extensionKick * 0.16;
        t.torsoY = -0.2 * extensionKick;
        t.headX = -0.1;
        t.lHipX = -0.2 - extensionKick * 1.28;
        t.lHipZ = 0.045 + extensionKick * 0.12;
        t.lKneeX = 0.28 - extensionKick * 0.25;
        t.rHipX = 0.16;
        t.rKneeX = 0.5 + extensionKick * 0.2;
        t.lArmX = -0.95;
        t.lArmZ = 0.46;
        t.lElbowX = -1.4;
        t.rArmX = -0.12;
        t.rArmZ = -0.72;
        t.rElbowX = -1.1;
        t.visualY = extensionKick * 0.025;
      } else if (key === "takedown") {
        const drive = Math.sin(Math.min(1, p / 0.55) * Math.PI * 0.5);
        t.torsoX = 0.08 + drive * 0.58;
        t.headX = drive * 0.16;
        t.lHipX = -0.2 - drive * 0.35;
        t.rHipX = 0.16 - drive * 0.18;
        t.lKneeX = 0.28 + drive * 0.5;
        t.rKneeX = 0.3 + drive * 0.42;
        t.lArmX = -0.56 - drive * 0.84;
        t.rArmX = -0.56 - drive * 0.84;
        t.lArmZ = 0.2 - drive * 0.12;
        t.rArmZ = -0.2 + drive * 0.12;
        t.lElbowX = -1.72 + drive * 1.32;
        t.rElbowX = -1.72 + drive * 1.32;
        t.visualY = -drive * 0.05;
      }
      return t;
    }

    return t;
  }

  _blendPose(target, rate, dt) {
    for (const key of Object.keys(target)) {
      this.pose[key] = damp(this.pose[key], target[key], rate, dt);
    }
  }

  _applyPose(bob, dt) {
    const p = this.pose;
    this.torso.rotation.set(p.torsoX, p.torsoY, p.torsoZ);
    this.head.rotation.set(p.headX, p.headY, p.headZ);

    this.armL.rotation.set(p.lArmX, p.lArmY, p.lArmZ);
    this.armR.rotation.set(p.rArmX, p.rArmY, p.rArmZ);

    // Elbows are children of shoulders.
    this.armL.children[1].rotation.set(p.lElbowX, p.lElbowY, p.lElbowZ);
    this.armR.children[1].rotation.set(p.rElbowX, p.rElbowY, p.rElbowZ);

    this.legL.hip.rotation.set(p.lHipX, p.lHipY, p.lHipZ);
    this.legR.hip.rotation.set(p.rHipX, p.rHipY, p.rHipZ);
    this.legL.knee.rotation.x = p.lKneeX;
    this.legR.knee.rotation.x = p.rKneeX;

    this.visual.position.y += bob;
    if (!this.ko && !this.downed) this.visual.position.y = Math.max(0, this.visual.position.y);
  }
}

