  }

  _buildCards() {
    this.el.cards.innerHTML = "";
    window.__FIGHTERS__?.forEach(() => {});
  }

  buildFighterCards(fighters) {
    this.fighterConfigs = fighters;
    this.el.cards.innerHTML = fighters
      .map(
        (f, index) => `
      <button class="fighter-card" role="option" aria-selected="${index === 0}" data-fighter="${index}"
        style="--accent:${f.accentCss}; --accent-soft:${f.accentSoft}; --accent-deep:${f.accentDeep}">
        <div class="card-bg"></div>
        <div class="card-lines"></div>
        <span class="card-num">0${index + 1}</span>
        <span class="card-flag">${f.flag}</span>
        <div class="silhouette">${SILHOUETTE}</div>
        <div class="card-info">
          <small>${f.style}</small>
          <strong>${f.last}</strong>
          <span>${f.nick}</span>
          <div class="card-statline">
            <i style="--v:${f.stats.striking / 100}"></i>
            <i style="--v:${f.stats.power / 100}"></i>
            <i style="--v:${f.stats.speed / 100}"></i>
          </div>
        </div>
      </button>`,
      )
      .join("");
  }

  selectCard(index, fighter, rival) {
    [...this.el.cards.children].forEach((card, i) => {
      card.classList.toggle("is-selected", i === index);
      card.setAttribute("aria-selected", String(i === index));
    });
    const set = (id, value) => {
      const node = document.getElementById(id);
      if (node) node.textContent = value;
    };
    set("selected-name", `${fighter.first}\n${fighter.last}`);
    document.getElementById("selected-name").innerHTML = `${fighter.first}<br>${fighter.last}`;
    set("selected-nickname", `“${fighter.nick}”`);
    set("selected-record", `${fighter.record} · ${fighter.height} · ${fighter.weight}`);
    document.getElementById("rival-name").innerHTML = `${rival.first}<br>${rival.last}`;
    set("rival-nickname", `“${rival.nick}”`);
    set("rival-record", `${rival.record} · ${rival.height} · ${rival.weight}`);
    set("select-opponent-name", rival.full);

    const stats = [
      ["striking", fighter.stats.striking],
      ["power", fighter.stats.power],
      ["speed", fighter.stats.speed],
      ["grapple", fighter.stats.grappling],
    ];
    for (const [name, value] of stats) {
      const bar = document.getElementById(`stat-${name}`);
      const num = document.getElementById(`stat-${name}-num`);
      if (bar) bar.style.transform = `scaleX(${value / 100})`;
      if (num) num.textContent = value;
    }
  }

  setFighters(p1, p2) {
    this.p1 = p1;
    this.p2 = p2;
    document.getElementById("hud-p1-name").textContent = p1.full;
    document.getElementById("hud-p1-nick").textContent = p1.nick;
    document.getElementById("hud-p1-record").textContent = p1.record.split("-").slice(0, 2).join("-");
    document.getElementById("hud-p2-name").textContent = p2.full;
    document.getElementById("hud-p2-nick").textContent = p2.nick;
    document.getElementById("hud-p2-record").textContent = p2.record.split("-").slice(0, 2).join("-");
    this.el.stance.textContent = p1.stance;
  }

  showScreen(name) {
    this.el.menu.classList.toggle("is-active", name === "menu");
    this.el.select.classList.toggle("is-active", name === "select");
    this.el.hud.classList.toggle("is-active", name === "fight");
    this.el.result.classList.toggle("is-active", name === "result");
    document.getElementById("app").classList.toggle("fight-live", name === "fight");
    this.el.touch.setAttribute("aria-hidden", name === "fight" ? "false" : "true");
  }

  hideLoading() {
    this.el.loading.classList.add("done");
  }

  setSound(enabled) {
    this.el.sound.classList.toggle("is-off", !enabled);
    this.el.sound.setAttribute("aria-pressed", String(enabled));
  }

  openModal(id) {
    document.getElementById(id)?.classList.add("is-open");
  }

  closeModal(id) {
    document.getElementById(id)?.classList.remove("is-open");
  }

  closeAllModals() {
    document.querySelectorAll(".modal").forEach((modal) => modal.classList.remove("is-open"));
  }

  resetForRound(round, time) {
    this.el.timer.textContent = this.formatTime(time);
    this.el.timer.classList.remove("is-low");
    this.el.roundLabel.textContent = `ROUND ${round}`;
    this.statusDefault = "";
    this.statusText("");
    this.lastRound = round;
  }

  formatTime(seconds) {
    const s = Math.max(0, Math.ceil(seconds));
    return `${Math.floor(s / 60)}:${String(s % 60).padStart(2, "0")}`;
  }

  updateHud(match, p1, p2) {
    if (!match) return;
    const hp = match.health;
    const stamina = match.stamina;
    this._bar("hud-p1-health", hp[0] / 100);
    this._bar("hud-p1-ghost", hp[0] / 100);
    this._bar("hud-p2-health", hp[1] / 100);
    this._bar("hud-p2-ghost", hp[1] / 100);
    this._bar("hud-p1-stamina", stamina[0] / 100);
    this._bar("hud-p2-stamina", stamina[1] / 100);

    document.getElementById("hud-p1-stamina").parentElement.classList.toggle("low", stamina[0] < 22);
    document.getElementById("hud-p2-stamina").parentElement.classList.toggle("low", stamina[1] < 22);

    this.el.timer.textContent = this.formatTime(match.roundTime);
    this.el.timer.classList.toggle("is-low", match.roundTime <= 10);
    this.el.roundLabel.textContent = `ROUND ${match.round}`;
    this.el.staminaLabel.textContent = String(Math.round(stamina[0]));

    for (let i = 0; i < 3; i++) {
      const p1El = document.getElementById("pips-p1").children[i];
      const p2El = document.getElementById("pips-p2").children[i];
      if (p1El) p1El.classList.toggle("won", i < match.roundWins[0]);
      if (p2El) p2El.classList.toggle("won", i < match.roundWins[1]);
    }

    const combo = match.combo[0];
    if (combo >= 2 && match.comboTimer[0] > 0) {
      this.el.combo.classList.add("show");
      this.el.comboNum.textContent = String(combo);
    } else {
      this.el.combo.classList.remove("show");
    }

    if (this.statusDefault) this._setStatus(this.statusDefault, false);
  }

  _bar(id, value) {
    const el = document.getElementById(id);
    if (el) el.style.transform = `scaleX(${Math.max(0, Math.min(1, value))})`;
  }

  setStatus(text, duration = 0) {
    this.statusDefault = text;
    this._setStatus(text, false);
    this.statusUntil = 0;
    if (duration) {
      this.statusUntil = performance.now() + duration * 1000;
    }
  }

  flashStatus(text, duration = 1.5) {
    this._setStatus(text, true);
    this.statusUntil = performance.now() + duration * 1000;
    this.statusDefault = "";
  }

  _setStatus(text, override) {
    if (!text) {
      this.el.status.style.opacity = "0";
      return;
    }
    if (this.lastStatus !== text) {
      this.el.statusText.textContent = text;
      this.lastStatus = text;
    }
    this.el.status.style.opacity = "1";
  }

  tickStatus() {
    if (this.statusUntil && performance.now() > this.statusUntil) {
      this.statusUntil = 0;
      this._setStatus(this.statusDefault || "", false);
    }
  }

  showRoundCard(kicker, big, message) {
    this.el.roundKicker.textContent = kicker;
    this.el.roundBig.textContent = big;
    this.el.roundMessage.textContent = message;
    this.el.roundCard.classList.remove("show");
    void this.el.roundCard.offsetWidth;
    this.el.roundCard.classList.add("show");
  }

  showAnnounce(main, sub) {
    this.el.announceMain.textContent = main;
    this.el.announceSub.textContent = sub;
    this.el.announce.classList.remove("show");
    void this.el.announce.offsetWidth;
    this.el.announce.classList.add("show");
  }

  showCallout(text, bonus) {
    this.el.calloutText.textContent = text;
    this.el.calloutBonus.textContent = bonus || "";
    this.el.callout.classList.remove("show");
    void this.el.callout.offsetWidth;
    this.el.callout.classList.add("show");
  }

  damageNumber(x, y, amount, type = "") {
    const node = document.createElement("div");
    node.className = `damage-number ${type}`;
    node.textContent = amount;
    node.style.left = `${x}px`;
    node.style.top = `${y}px`;
    this.el.damageLayer.appendChild(node);
    window.setTimeout(() => node.remove(), 900);
  }

  flashScreen(strength = 1) {
    this.flash.classList.remove("show");
    void this.flash.offsetWidth;
    this.flash.style.setProperty("--strength", String(Math.min(1, strength)));
    this.flash.classList.add("show");
  }

  showResult(data) {
    this.el.resultTitle.textContent = data.title;
    this.el.resultTitle.classList.toggle("loss", !data.playerWon);
    this.el.resultMethod.textContent = data.method;
    this.el.resultTime.textContent = data.detail;
    this.el.resultWinner.innerHTML = `<small>WINNER</small><strong>${data.winner.full}</strong><span>${data.winner.nick}</span>`;
    this.el.resultLoser.innerHTML = `<small>DEFEATED</small><strong>${data.loser.full}</strong><span>${data.loser.nick}</span>`;
    this.el.resultStats.innerHTML = data.stats
      .map(
        (stat) => `<div class="result-stat"><b>${stat.value}</b><span>${stat.label}</span></div>`,
      )
      .join("");
    this.el.resultEvent.textContent = `FIGHT NIGHT 07 · ${data.playerWon ? "VICTORY" : "DEFEAT"}`;
    this.showScreen("result");
  }

  hideResult() {
    this.el.result.classList.remove("is-active");
  }

  showCardOrResult() {}
}

import * as THREE from "three";

function rand(min, max) {
  return min + Math.random() * (max - min);
}

export class Effects {
  constructor(scene) {
    this.scene = scene;
    this.items = [];
  }

  impact(position, color = 0xffb15a, power = 1, count = 20) {
    const geometry = new THREE.BufferGeometry();
    const positions = new Float32Array(count * 3);
    const velocities = [];
    for (let i = 0; i < count; i++) {
      positions[i * 3] = rand(-0.06, 0.06);
      positions[i * 3 + 1] = rand(-0.06, 0.06);
      positions[i * 3 + 2] = rand(-0.06, 0.06);
      velocities.push(
        new THREE.Vector3(rand(-1, 1), rand(-0.2, 1.15), rand(-1, 1))
          .normalize()
          .multiplyScalar(rand(0.9, 3.6) * power),
      );
    }
    geometry.setAttribute("position", new THREE.BufferAttribute(positions, 3));
    const material = new THREE.PointsMaterial({
      color,
      size: 0.07 * power,
      transparent: true,
      opacity: 1,
      depthWrite: false,
      blending: THREE.AdditiveBlending,
      sizeAttenuation: true,
    });
    const points = new THREE.Points(geometry, material);
    points.position.copy(position);
    this.scene.add(points);
    this.items.push({ type: "impact", object: points, velocities, life: 0.7, maxLife: 0.7 });
  }

  confetti(playerColors = [0xff2f38, 0xf7f2e8, 0xffc14a], count = 220) {
    const geometry = new THREE.BufferGeometry();
    const positions = new Float32Array(count * 3);
    const colors = new Float32Array(count * 3);
    const velocities = [];
    const palette = playerColors.map((hex) => new THREE.Color(hex));
    for (let i = 0; i < count; i++) {
      const angle = Math.random() * Math.PI * 2;
      const radius = Math.random() * 3.2;
      positions[i * 3] = Math.cos(angle) * radius;
      positions[i * 3 + 1] = 5.5 + Math.random() * 2.6;
      positions[i * 3 + 2] = Math.sin(angle) * radius;
      const color = palette[(Math.random() * palette.length) | 0];
      colors[i * 3] = color.r;
      colors[i * 3 + 1] = color.g;
      colors[i * 3 + 2] = color.b;
      velocities.push(new THREE.Vector3(rand(-0.4, 0.4), rand(-1.4, -0.5), rand(-0.4, 0.4)));
    }
    geometry.setAttribute("position", new THREE.BufferAttribute(positions, 3));
    geometry.setAttribute("color", new THREE.BufferAttribute(colors, 3));
    const material = new THREE.PointsMaterial({
      size: 0.1,
      vertexColors: true,
      transparent: true,
      opacity: 0.95,
      depthWrite: false,
      sizeAttenuation: true,
    });
    const points = new THREE.Points(geometry, material);
    points.position.set(0, 0.57, 0);
    this.scene.add(points);
    this.items.push({ type: "confetti", object: points, velocities, life: 6, maxLife: 6 });
  }

  update(dt) {
    for (let i = this.items.length - 1; i >= 0; i--) {
      const item = this.items[i];
      item.life -= dt;
      const pos = item.object.geometry.attributes.position;
      const drag = item.type === "impact" ? 0.9 : 1;
      for (let j = 0; j < pos.count; j++) {
        const vel = item.velocities[j];
        if (!vel) continue;
        vel.y -= (item.type === "impact" ? 7.8 : 1.7) * dt;
        vel.multiplyScalar(Math.pow(drag, dt * 60));
        pos.setXYZ(j, pos.getX(j) + vel.x * dt, pos.getY(j) + vel.y * dt, pos.getZ(j) + vel.z * dt);
      }
      pos.needsUpdate = true;
      const t = Math.max(0, item.life / item.maxLife);
      if (item.type === "impact") {
        item.object.material.opacity = t;
        item.object.material.size = 0.035 + t * 0.05;
      } else {
        item.object.material.opacity = Math.min(1, t * 2.2);
      }
      if (item.life <= 0) {
        this.scene.remove(item.object);
        item.object.geometry.dispose();
        item.object.material.dispose();
        this.items.splice(i, 1);
      }
    }
  }
}

import * as THREE from "three";
import { AI_PROFILES, MAX_ROUNDS, MOVES, RING_RADIUS, ROUND_SECONDS } from "./config.js";

const clamp = (v, a, b) => Math.max(a, Math.min(b, v));
const random = (a, b) => a + Math.random() * (b - a);
const forwardFromYaw = (yaw) => new THREE.Vector3(Math.sin(yaw), 0, Math.cos(yaw));

/**
 * Owns all moment-to-moment fight simulation: movement, strikes, stamina,
 * AI decisions, damage, scoring and round data.
 */
export class Combat {
  constructor(game) {
    this.g = game;
    this.match = null;
    this.aiCooldown = 0;
    this.aiBlockTimer = 0;
    this.aiStrafe = Math.random() > 0.5 ? 1 : -1;
    this.aiStrafeTimer = 1.2;
    this.aiReactedAction = null;
    this.knockback = [new THREE.Vector3(), new THREE.Vector3()];
    this.lastPlayerMove = null;
    this.aiTauntTimer = 4;
  }

  begin(p1, p2, rivalProfile) {
    this.p1 = p1;
    this.p2 = p2;
    this.profile = AI_PROFILES[rivalProfile] || AI_PROFILES.okafor;
    this.match = {
      health: [100, 100],
      stamina: [100, 100],
      round: 1,
      roundTime: ROUND_SECONDS,
      roundWins: [0, 0],
      combo: [0, 0],
      comboTimer: [0, 0],
      roundDamage: [0, 0],
      stats: [
        { strikes: 0, landed: 0, damage: 0, takedowns: 0, knockdowns: 0, blocks: 0 },
        { strikes: 0, landed: 0, damage: 0, takedowns: 0, knockdowns: 0, blocks: 0 },
      ],
      lastRoundWin: null,
    };
    this.aiCooldown = 0.9;
    this.aiBlockTimer = 0;
    this.aiReactedAction = null;
    this.knockback[0].set(0, 0, 0);
    this.knockback[1].set(0, 0, 0);
    this.resetRoundState(1, true);
  }

  resetRoundState(round, full = false) {
    const m = this.match;
    if (!m) return;
    m.round = round;
    m.roundTime = ROUND_SECONDS;
    m.combo = [0, 0];
    m.comboTimer = [0, 0];
    m.roundDamage = [0, 0];
    m.stamina = [100, 100];
    if (full) {
      m.health = [100, 100];
      m.roundWins = [0, 0];
      m.stats = [
        { strikes: 0, landed: 0, damage: 0, takedowns: 0, knockdowns: 0, blocks: 0 },
        { strikes: 0, landed: 0, damage: 0, takedowns: 0, knockdowns: 0, blocks: 0 },
      ];
    } else {
      m.health = [Math.min(100, m.health[0] + 9), Math.min(100, m.health[1] + 9)];
    }
    this.aiCooldown = 0.85;
    this.aiBlockTimer = 0;
    this.aiReactedAction = null;
    this.knockback[0].set(0, 0, 0);
    this.knockback[1].set(0, 0, 0);
  }

  update(dt) {
    const g = this.g;
    const m = this.match;
    if (!m || g.state !== "fight") return;

    m.roundTime -= dt;
    if (m.roundTime <= 0) {
      m.roundTime = 0;
      g.onRoundTimeExpired();
      return;
    }

    for (let i = 0; i < 2; i++) {
      if (m.comboTimer[i] > 0) m.comboTimer[i] -= dt;
      else m.combo[i] = 0;
    }

    const p1 = this.p1;
    const p2 = this.p2;

    // Player block state
    if (!p1.downed && !p1.ko) {
      p1.setBlocking(g.blockHeld && m.stamina[0] > 0 && !p1.action);
    }

    // Player locomotion
    const input = g.getMoveInput();
    const dir = this._fightDirection();
    const right = new THREE.Vector3(dir.z, 0, -dir.x);
    const playerMove = new THREE.Vector3()
      .addScaledVector(dir, input.forward)
      .addScaledVector(right, input.strafe);
    if (playerMove.lengthSq() > 1) playerMove.normalize();
    const playerSpeed = p1.config.speed * 2.55 * (p1.blocking ? 0.42 : 1) * (p1.action ? 0.26 : 1);
    this._moveFighter(p1, playerMove, playerSpeed, dt, 0);

    // AI brain
    this._updateAI(dt);

    // Physics / bodies
    this._separateBodies(dt);
    this._applyKnockback(dt);

    // Face each other
    const dx = p2.root.position.x - p1.root.position.x;
    const dz = p2.root.position.z - p1.root.position.z;
    p1.setFacing(dx, dz, dt);
    p2.setFacing(-dx, -dz, dt);

    // Animate rigs
    const p1Speed = playerMove.length() * playerSpeed;
    const p2Speed = this.aiMove ? this.aiMove.length() * (this.lastAiSpeed || 0) : 0;
    p1.update(dt, g.time, Math.min(1, p1Speed / 3.5));
    p2.update(dt, g.time, Math.min(1, p2Speed / 3.5));

    // Resolve strikes right after animation time advances.
    this._resolvePending(p1, p2, 0);
    this._resolvePending(p2, p1, 1);

    // Stamina economy
    for (let i = 0; i < 2; i++) {
      const f = i === 0 ? p1 : p2;
      let regen = f.blocking ? 2.2 : f.downed ? 6 : f.action ? 0.7 : 7.4;
      if (m.stamina[i] < 16 && !f.action) regen *= 0.45;
      m.stamina[i] = clamp(m.stamina[i] + regen * dt, 0, 100);
    }

    // Contextual coaching line
    const distance = Math.hypot(dx, dz);
    if (!g.ui.statusUntil) {
      if (p1.downed) g.ui.setStatus("GET BACK TO YOUR FEET");
      else if (m.health[0] < 24) g.ui.setStatus("DIG DEEP · SURVIVE THE ROUND");
      else if (m.health[1] < 24) g.ui.setStatus("HE'S HURT · FINISH HIM");
      else if (m.stamina[0] < 16) g.ui.setStatus("LOW STAMINA · CREATE SPACE");
      else if (distance > 2.5) g.ui.setStatus("CLOSE THE DISTANCE");
      else if (p2.blocking) g.ui.setStatus("THE GUARD IS UP · GO LOW");
      else g.ui.setStatus("READ THE OPENING");
    }
  }

  _fightDirection() {
    const d = new THREE.Vector3(
      this.p2.root.position.x - this.p1.root.position.x,
      0,
      this.p2.root.position.z - this.p1.root.position.z,
    );
    if (d.lengthSq() < 0.0001) d.set(1, 0, 0);
    return d.normalize();
  }

  _moveFighter(fighter, moveVector, speed, dt, index) {
    if (fighter.downed || fighter.ko) return;
    const deadzone = 0.08;
    if (moveVector.lengthSq() < deadzone * deadzone) return;
    fighter.root.position.addScaledVector(moveVector, speed * dt);
    this._clampToRing(fighter);
  }

  _clampToRing(fighter) {
    const pos = fighter.root.position;
    const length = Math.hypot(pos.x, pos.z);
    const limit = RING_RADIUS - 0.28;
    if (length > limit) {
      pos.x = (pos.x / length) * limit;
      pos.z = (pos.z / length) * limit;
    }
  }

  _separateBodies(dt) {
    if (this.p1.downed || this.p2.downed) return;
    const a = this.p1.root.position;
    const b = this.p2.root.position;
    const dx = b.x - a.x;
    const dz = b.z - a.z;
    const dist = Math.hypot(dx, dz);
    const min = 0.92;
    if (dist > 0.0001 && dist < min) {
      const push = (min - dist) * 0.5;
      a.x -= (dx / dist) * push;
      a.z -= (dz / dist) * push;
      b.x += (dx / dist) * push;
      b.z += (dz / dist) * push;
      this._clampToRing(this.p1);
      this._clampToRing(this.p2);
    }
  }

  _applyKnockback(dt) {
    for (let i = 0; i < 2; i++) {
      const f = i === 0 ? this.p1 : this.p2;
      if (this.knockback[i].lengthSq() < 0.0001) continue;
      f.root.position.addScaledVector(this.knockback[i], dt);
      this.knockback[i].multiplyScalar(Math.pow(0.006, dt));
      if (this.knockback[i].lengthSq() < 0.01) this.knockback[i].set(0, 0, 0);
      this._clampToRing(f);
    }
  }

  _updateAI(dt) {
    const p1 = this.p1;
    const p2 = this.p2;
    const m = this.match;
    if (p2.downed || p2.ko || p1.ko) {
      p2.setBlocking(false);
      this.aiMove = new THREE.Vector3();
      return;
    }

    const profile = this.profile;
    const dx = p1.root.position.x - p2.root.position.x;
    const dz = p1.root.position.z - p2.root.position.z;
    const dist = Math.hypot(dx, dz);
    const toward = new THREE.Vector3(dx, 0, dz).normalize();

    this.aiCooldown -= dt;
    this.aiBlockTimer -= dt;
    this.aiStrafeTimer -= dt;
    this.aiTauntTimer -= dt;

    // React to a new player strike with a chance to shell up.
    if (p1.action && p1.action !== this.aiReactedAction) {
      this.aiReactedAction = p1.action;
      if (dist < 2.7 && m.stamina[1] > 12 && Math.random() < profile.block * 0.92) {
        this.aiBlockTimer = random(0.28, 0.62);
        this.g.sound?.whoosh(false);
      }
    }
    if (!p1.action) this.aiReactedAction = null;

    p2.setBlocking(this.aiBlockTimer > 0 && m.stamina[1] > 0 && !p2.action);

    if (this.aiStrafeTimer <= 0) {
      this.aiStrafe = Math.random() > 0.5 ? 1 : -1;
      this.aiStrafeTimer = random(0.9, 2.4);
    }

    const desired = new THREE.Vector3();
    const preferred = p2.config.id === "okafor" ? 1.65 : 1.85;
    const retreat = m.stamina[1] < 18 || (m.health[1] < 18 && Math.random() < 0.35);

    if (retreat) {
      if (dist < 2.6) desired.addScaledVector(toward, -1);
      desired.addScaledVector(new THREE.Vector3(toward.z, 0, -toward.x), this.aiStrafe * 0.9);
      if (dist > 3.4) desired.addScaledVector(toward, 0.55);
    } else {
      if (dist > preferred + 0.25) desired.addScaledVector(toward, 1);
      else if (dist < preferred - 0.32) desired.addScaledVector(toward, -0.65);
      desired.addScaledVector(new THREE.Vector3(toward.z, 0, -toward.x), this.aiStrafe * (dist < 3.1 ? 0.26 : 0.55));
    }
    if (p2.action || p2.blocking) desired.multiplyScalar(0.15);
    if (desired.lengthSq() > 1) desired.normalize();

    const speed = p2.config.speed * 2.42 * (p2.blocking ? 0.38 : 1) * (m.stamina[1] < 18 ? 0.74 : 1);
    this.aiMove = desired;
    this.lastAiSpeed = speed;
    this._moveFighter(p2, desired, speed, dt, 1);

    if (p2.action || p2.blocking || p1.downed) return;

    if (this.aiCooldown <= 0 && dist < 2.48 && m.stamina[1] > 8) {
      const options = [
        { key: "jab", w: 0.46 },
        { key: "heavy", w: 0.26 },
        { key: "kick", w: dist < 2.35 ? 0.19 : 0 },
        { key: "takedown", w: dist < 2.0 ? profile.takedown : 0 },
      ];
      let roll = Math.random() * options.reduce((sum, option) => sum + option.w, 0);
      let chosen = "jab";
      for (const option of options) {
        roll -= option.w;
        if (roll <= 0) {
          chosen = option.key;
          break;
        }
      }
      // Don't waste big moves at max stamina if opponent is circling away.
      if (chosen === "heavy" && Math.random() < 0.22) chosen = "jab";
      if (this.attack(chosen, false)) {
        this.aiCooldown = random(0.34, 0.88) / (0.5 + profile.patience * 0.5);
      }
    } else if (this.aiCooldown <= 0 && dist > 3.4 && Math.random() < 0.35 * dt * 6) {
      // occasional circling feint
      this.aiStrafeTimer = 0.5;
    }

    // The champion talks with his hands.
    if (m.health[0] < 18 && p1.downed && this.aiTauntTimer <= 0) {
      this.aiTauntTimer = 6;
      p2.setVictory(true);
      setTimeout(() => p2.setVictory(false), 900);
    }
  }

  attack(key, isPlayer) {
    if (this.g.state !== "fight") return false;
    const idx = isPlayer ? 0 : 1;
    const fighter = idx === 0 ? this.p1 : this.p2;
    const m = this.match;
    const move = MOVES[key];
    if (!move || !m || fighter.downed || fighter.ko) return false;
    if (fighter.action) return false;
    if (m.stamina[idx] < move.stamina) {
      if (isPlayer) {
        this.g.ui.flashStatus("NOT ENOUGH STAMINA", 1.1);
        this.g.sound?.ui(false);
      }
      return false;
    }
    fighter.setBlocking(false);
    if (!fighter.playMove(key)) return false;
    m.stamina[idx] = Math.max(0, m.stamina[idx] - move.stamina);
    m.stats[idx].strikes += 1;
    this.g.sound?.whoosh(key !== "jab");
    if (isPlayer) {
      this.g.ui.setStatus("", 0);
      if (key === "takedown") this.g.ui.flashStatus("TAKEDOWN ATTEMPT", 0.7);
    }
    return true;
  }

  _resolvePending(attacker, defender, idx) {
    const action = attacker.action;
    if (!action || action.hitConsumed || action.t < action.move.hitAt) return;
    action.hitConsumed = true;
    if (defender.ko) return;

    const dx = defender.root.position.x - attacker.root.position.x;
    const dz = defender.root.position.z - attacker.root.position.z;
    const dist = Math.hypot(dx, dz);
    const fwd = forwardFromYaw(attacker.yaw);
    const dot = dist < 0.0001 ? 1 : (dx / dist) * fwd.x + (dz / dist) * fwd.z;
    const move = action.move;

    if (dist > move.range + 0.28 || dot < 0.2) {
      if (idx === 0) this.g.ui.flashStatus("WHIFF · RESET YOUR FEET", 0.7);
      return;
    }
    if (defender.downed || defender.invulnerable > 0) return;

    const m = this.match;
    let blocked = defender.blocking && m.stamina[1 - idx] > 0;
    let guardBreak = false;
    let counter = false;
    if (defender.action && defender.action.t < defender.action.move.hitAt && !blocked) {
      counter = Math.random() < (idx === 0 ? 0.88 : 0.7);
    }

    let damage = move.damage * attacker.config.power * random(0.93, 1.07);
    if (blocked) {
      m.stamina[1 - idx] = Math.max(0, m.stamina[1 - idx] - (move.key === "takedown" ? 16 : 11));
      if (m.stamina[1 - idx] <= 0) {
        guardBreak = true;
        blocked = false;
        damage *= 0.62;
        if (idx === 0) this.g.ui.flashStatus("GUARD BROKEN", 1.2);
      } else {
        damage *= move.key === "takedown" ? 0.12 : 0.16;
      }
    }
    if (counter) damage *= 1.34;
    damage = Math.max(0.5, damage);

    const healthKey = 1 - idx;
    m.health[healthKey] = Math.max(0, m.health[healthKey] - damage);
    m.roundDamage[idx] += damage;
    m.stats[idx].damage += damage;
    m.stats[idx].landed += 1;
    if (blocked) m.stats[healthKey].blocks += 1;

    // Combos only count clean or guard-breaking hits.
    if (!blocked && !guardBreak) {
      m.combo[idx] += 1;
      m.comboTimer[idx] = 1.75;
    } else {
      m.combo[idx] = 0;
    }

    const hitPos = defender.root.position.clone();
    hitPos.y += 1.62;
    if (blocked) {
      this.g.sound?.punch(0.75, true);
      this.g.effects.impact(hitPos, 0x9fc6ff, 0.7, 10);
      this.g.shake = Math.min(1.4, this.g.shake + 0.16);
      defender.takeHit(false);
      this._damageNumber(hitPos, "BLOCK", "block");
    } else if (guardBreak) {
      this.g.sound?.punch(1.2, false);
      this.g.effects.impact(hitPos, 0xffb54a, 1.2, 24);
      this.g.shake = Math.min(1.6, this.g.shake + 0.5);
      defender.takeHit(true);
      this._damageNumber(hitPos, Math.round(damage), "heavy");
      if (idx === 1) this.g.ui.flashScreen(0.75);
    } else {
      const heavy = move.damage >= 12;
      this.g.sound?.punch(heavy ? 1.28 : 0.9, false);
      this.g.effects.impact(hitPos, counter ? 0xffffff : heavy ? 0xffa234 : 0xffd092, heavy ? 1.35 : 0.85, heavy ? 28 : 14);
      this.g.shake = Math.min(1.8, this.g.shake + (heavy ? 0.62 : 0.26));
      defender.takeHit(heavy);
      this._damageNumber(hitPos, Math.round(damage), heavy ? "heavy" : "");
      if (idx === 1) this.g.ui.flashScreen(heavy ? 0.85 : 0.45);
    }

    if (counter) {
      defender.cancelAction();
      if (idx === 0) this.g.ui.showCallout("COUNTER", "+34% DAMAGE");
      this.g.sound?.punch(1, false, 0.03);
    } else if (guardBreak && idx === 0) {
      this.g.ui.showCallout("GUARD BREAK", "STAMINA DRAINED");
    } else if (heavy && !blocked && idx === 0 && Math.random() < 0.16) {
      this.g.ui.showCallout("CLEAN SHOT", "MOMENTUM SHIFT");
    }

    // Knockback
    const pushDir = new THREE.Vector3(dx, 0, dz).normalize();
    this.knockback[healthKey].addScaledVector(pushDir, move.push * (blocked ? 0.5 : 1));
    if (move.key === "kick" && !blocked) {
      this.knockback[healthKey].addScaledVector(pushDir, 0.42);
    }

    // Takedowns put opponents on the mat.
    if (move.key === "takedown" && !blocked) {
      m.stats[idx].takedowns += 1;
      m.stats[idx].knockdowns += 1;
      defender.knockDown(random(2.2, 2.9));
      this.g.sound?.takedown();
      this.g.ui.showAnnounce("TAKEDOWN", "POSITION SECURED");
      this.g.ui.flashStatus(idx === 0 ? "TAKEDOWN · STAY ON HIM" : "TAKEN DOWN · FIGHT BACK", 1.6);
    }

    if (m.health[healthKey] <= 0) {
      this.g.beginKO(idx);
      return;
    }

    // Flashdowns from big kicks at low stamina.
    if (!blocked && move.key === "kick" && m.stamina[healthKey] < 9 && m.health[healthKey] < 55) {
      defender.knockDown(1.5);
      m.stats[idx].knockdowns += 1;
      this.g.ui.showAnnounce("FLASH DOWN", "MOMENTUM SHIFT");
    }
  }

  _damageNumber(worldPos, value, type) {
    const screen = this.g.projectToScreen(worldPos);
    if (screen) this.g.ui.damageNumber(screen.x, screen.y, value, type);
  }

  finishRound() {
    const m = this.match;
    if (!m) return null;
    let winner = -1;
    if (m.roundDamage[0] > m.roundDamage[1] + 0.2) winner = 0;
    else if (m.roundDamage[1] > m.roundDamage[0] + 0.2) winner = 1;
    if (winner >= 0) m.roundWins[winner] += 1;
    m.lastRoundWin = winner;
    return {
      winner,
      damage: [...m.roundDamage],
      roundWins: [...m.roundWins],
    };
  }

  decide() {
    const m = this.match;
    if (!m) return null;
    let winner = -1;
    if (m.roundWins[0] !== m.roundWins[1]) winner = m.roundWins[0] > m.roundWins[1] ? 0 : 1;
    else {
      const total0 = m.stats[0].damage;
      const total1 = m.stats[1].damage;
      if (Math.abs(total0 - total1) > 0.2) winner = total0 > total1 ? 0 : 1;
      else if (m.health[0] !== m.health[1]) winner = m.health[0] > m.health[1] ? 0 : 1;
    }
    return winner;
  }

  isFinalRound() {
    return this.match && this.match.round >= MAX_ROUNDS;
  }
}

import * as THREE from "three";
import { EffectComposer } from "three/addons/postprocessing/EffectComposer.js";
import { RenderPass } from "three/addons/postprocessing/RenderPass.js";
import { UnrealBloomPass } from "three/addons/postprocessing/UnrealBloomPass.js";
import { OutputPass } from "three/addons/postprocessing/OutputPass.js";
import { Arena } from "./arena.js";
import { Fighter } from "./fighter.js";
import { SoundEngine } from "./audio.js";
import { Combat } from "./combat.js";
import { Effects } from "./effects.js";
import { GameUI } from "./ui.js";
import {
  FIGHTERS,
  FIGHTER_BY_ID,
  MAX_ROUNDS,
  RING_RADIUS,
  RIVALS,
  ROUND_SECONDS,
} from "./config.js";

const TAU = Math.PI * 2;
const BASE_Y = 0.57;
const clamp = (value, min, max) => Math.max(min, Math.min(max, value));
const damp = (current, target, rate, dt) => current + (target - current) * (1 - Math.exp(-rate * dt));
const formatTime = (seconds) => {
  const s = Math.max(0, Math.ceil(seconds));
  return `${Math.floor(s / 60)}:${String(s % 60).padStart(2, "0")}`;
};

export class Game {
  constructor() {
    this.app = document.getElementById("app");
    this.canvas = document.getElementById("scene");
    this.ui = new GameUI();
    this.audio = new SoundEngine();
    this.state = "loading";
    this.time = 0;
    this.timeScale = 1;
    this.shake = 0;
    this.selectedIndex = 0;
    this.rivalId = RIVALS[FIGHTERS[0].id];
    this.keys = new Set();
    this.keyboardBlock = false;
    this.touchBlock = false;
    this.blockHeld = false;
    this.touchMove = { x: 0, y: 0, active: false };
    this.roundIntroTimer = 0;
    this.roundEndTimer = 0;
    this.koTimer = 0;
    this.koWinner = 0;
    this.finishDetail = "";
    this.pausedFrom = "fight";
    this.howtoOpen = false;
    this.soundEnabled = this._readSoundPref();
    this.showcase = [];
    this.selectionRings = [];
    this.fighters = null;

    this._initRenderer();
    this._initScene();
    this._initShowcase();
    this._initCombat();
    this._bindInput();
    this._bindUi();
    this._updateSelectUi();
    this.audio.setEnabled(this.soundEnabled);
    this.ui.setSound(this.soundEnabled);

    this.state = "menu";
    this.ui.showScreen("menu");
    this.arena.setScreen({ left: "KAI MORENO", right: "MARCUS OKAFOR", round: "FIGHT NIGHT 07" });
    this.camera.position.set(0, 3.2, 5.4);
    this.camLook.set(0, 1.25, 0);
    this.camera.lookAt(this.camLook);

    this.lastFrame = performance.now();
    this._loop = this._loop.bind(this);
    requestAnimationFrame(this._loop);
    window.setTimeout(() => this.ui.hideLoading(), 850);
    window.__OCTAGON__ = this;
  }

  _readSoundPref() {
    try {
      return localStorage.getItem("octagon-sound") !== "off";
    } catch {
      return true;
    }
  }

  _initRenderer() {
    this.renderer = new THREE.WebGLRenderer({
      canvas: this.canvas,
      antialias: true,
      powerPreference: "high-performance",
      alpha: false,
    });
    this.renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 1.55));
    this.renderer.setSize(window.innerWidth, window.innerHeight);
    this.renderer.outputColorSpace = THREE.SRGBColorSpace;
    this.renderer.toneMapping = THREE.ACESFilmicToneMapping;
    this.renderer.toneMappingExposure = 1.04;
    this.renderer.shadowMap.enabled = true;
    this.renderer.shadowMap.type = THREE.PCFSoftShadowMap;
  }

  _initScene() {
    this.scene = new THREE.Scene();
    this.scene.background = new THREE.Color(0x05060a);
    this.scene.fog = new THREE.FogExp2(0x06070b, 0.017);
    this.camera = new THREE.PerspectiveCamera(50, window.innerWidth / window.innerHeight, 0.1, 70);
    this.camLook = new THREE.Vector3(0, 1.25, 0);
    this.arena = new Arena(this.scene, this.renderer);
    this.effects = new Effects(this.scene);

    this.usePost = !window.matchMedia("(pointer: coarse)").matches && window.devicePixelRatio < 2.5;
    if (this.usePost) {
      this.composer = new EffectComposer(this.renderer);
      this.composer.addPass(new RenderPass(this.scene, this.camera));
      this.bloom = new UnrealBloomPass(new THREE.Vector2(window.innerWidth, window.innerHeight), 0.34, 0.58, 0.85);
      this.composer.addPass(this.bloom);
      this.composer.addPass(new OutputPass());
    }

    window.addEventListener("resize", () => this._resize());
  }

  _initShowcase() {
    const spacing = 2.12;
    FIGHTERS.forEach((config, index) => {
      const fighter = new Fighter(config, "showcase");
      fighter.setBaseY(BASE_Y);
      fighter.root.position.set((index - 1) * spacing, BASE_Y, 0);
      fighter.root.rotation.y = 0;
      fighter.yaw = 0;
      fighter.showcaseTimer = 1.5 + index * 1.7;
      this.scene.add(fighter.root);
      this.showcase.push(fighter);

      const ring = new THREE.Mesh(
        new THREE.RingGeometry(0.56, 0.63, 48),
        new THREE.MeshBasicMaterial({
          color: config.accent,
          transparent: true,
          opacity: 0.26,
          side: THREE.DoubleSide,
          blending: THREE.AdditiveBlending,
          depthWrite: false,
        }),
      );
      ring.rotation.x = -Math.PI / 2;
      ring.position.set((index - 1) * spacing, BASE_Y + 0.008, 0);
      this.scene.add(ring);
      this.selectionRings.push(ring);
    });
  }

  _initCombat() {
    this.combat = new Combat(this);
    this.match = null;
    this.p1 = null;
    this.p2 = null;
  }

  startFight() {
    if (!["menu", "select", "result", "paused"].includes(this.state)) return;
    this._ensureAudio();
    const playerConfig = FIGHTERS[this.selectedIndex];
    const rivalConfig = FIGHTER_BY_ID[this.rivalId];
    if (!rivalConfig) return;

    this._disposeFightFighters();
    this.p1 = new Fighter(playerConfig, "left");
    this.p2 = new Fighter(rivalConfig, "right");
    this.p1.setBaseY(BASE_Y);
    this.p2.setBaseY(BASE_Y);
    this.scene.add(this.p1.root, this.p2.root);
    this.fighters = [this.p1, this.p2];
    this.showcase.forEach((fighter) => {
      fighter.root.visible = false;
    });
    this.selectionRings.forEach((ring) => {
      ring.visible = false;
    });

    this.combat.begin(this.p1, this.p2, this.rivalId);
    this.match = this.combat.match;
    this.ui.setFighters(playerConfig, rivalConfig);
    this.ui.closeAllModals();
    this.ui.hideResult();
    this.ui.showScreen("fight");
    this.ui.resetForRound(1, ROUND_SECONDS);
    this.arena.setScreen({ left: playerConfig.last, right: rivalConfig.last, round: "ROUND 1" });
    this._placeFighters();
    this.state = "roundIntro";
    this.roundIntroTimer = 1.7;
    this.timeScale = 1;
    this.shake = 0;
    this.ui.showRoundCard("ROUND ONE", "1", "FIGHT");
    this.audio.startCrowd();
    this.audio.cheer(0.65);
    this.ui.setStatus("TAP INTO THE CROWD");
    this.keyboardBlock = false;
    this.touchBlock = false;
    this.blockHeld = false;
    this.ui.updateHud(this.match, playerConfig, rivalConfig);
  }

  _placeFighters() {
    if (!this.p1 || !this.p2) return;
    this.p1.root.position.set(-1.12, BASE_Y, 0);
    this.p2.root.position.set(1.12, BASE_Y, 0);
    this.p1.yaw = Math.PI / 2;
    this.p2.yaw = -Math.PI / 2;
    this.p1.root.rotation.y = Math.PI / 2;
    this.p2.root.rotation.y = -Math.PI / 2;
    this.p1.setFacing(1, 0, 1);
    this.p2.setFacing(-1, 0, 1);
  }

  _disposeFightFighters() {
    if (!this.fighters) return;
    for (const fighter of this.fighters) {
      this.scene.remove(fighter.root);
    }
    this.fighters = null;
    this.p1 = null;
    this.p2 = null;
  }

  beginRound(round) {
    this.combat.resetRoundState(round, false);
    this.p1.reset();
    this.p2.reset();
    this._placeFighters();
    this.state = "roundIntro";
    this.roundIntroTimer = 1.65;
    this.timeScale = 1;
    this.blockHeld = false;
    this.keyboardBlock = false;
    this.touchBlock = false;
    this.ui.resetForRound(round, ROUND_SECONDS);
    this.ui.showRoundCard(round === 1 ? "ROUND ONE" : round === 2 ? "ROUND TWO" : "FINAL ROUND", String(round), "FIGHT");
    this.arena.setScreen({ left: this.p1.config.last, right: this.p2.config.last, round: `ROUND ${round}` });
    this.audio.cheer(0.6);
    this.ui.updateHud(this.match);
  }

  onRoundTimeExpired() {
    if (this.state !== "fight") return;
    this.state = "roundEnd";
    this.roundEndTimer = 3.4;
    this.timeScale = 1;
    this.audio.bell(3);
    const summary = this.combat.finishRound();
    this.ui.updateHud(this.match);
    this.ui.showRoundCard("ROUND " + this.match.round, "TIME", "ROUND OVER");
    let sub = "SCORECARDS ARE IN";
    if (summary?.winner === 0) sub = "YOU TOOK THE ROUND";
    if (summary?.winner === 1) sub = `${this.p2.config.last} TOOK THE ROUND`;
    this.ui.flashStatus(sub, 3);
    this.ui.setStatus(sub);
    this.audio.cheer(0.8);
  }

  beginKO(winnerIndex) {
    if (this.state !== "fight") return;
    const loser = winnerIndex === 0 ? this.p2 : this.p1;
    const winner = winnerIndex === 0 ? this.p1 : this.p2;
    this.match.health[1 - winnerIndex] = 0;
    this.state = "ko";
    this.koWinner = winnerIndex;
    this.koTimer = 0;
    this.timeScale = 0.3;
    this.finishDetail = `ROUND ${this.match.round} · ${formatTime(ROUND_SECONDS - this.match.roundTime)}`;
    loser.setKO();
    winner.cancelAction();
    winner.setBlocking(false);
    this.ui.showAnnounce("KO", winnerIndex === 0 ? "KNOCKOUT" : "YOU'RE OUT");
    this.ui.flashStatus("IT'S ALL OVER", 4.5);
    this.ui.flashScreen(1);
    this.audio.ko();
    this.audio.cheer(1.8);
    this.shake = 1.8;
    this.keyboardBlock = false;
    this.touchBlock = false;
    this.blockHeld = false;
  }

  finishDecision() {
    let winner = this.combat.decide();
    if (winner < 0) winner = this.match.health[0] >= this.match.health[1] ? 0 : 1;
    const method = Math.abs(this.match.roundWins[0] - this.match.roundWins[1]) >= 2 ? "UNANIMOUS DECISION" : "SPLIT DECISION";
    this.finishMatch(winner, method, "3 ROUNDS COMPLETE");
  }

  finishMatch(winnerIndex, method, detail) {
    this.state = "result";
    this.timeScale = 1;
    const playerWon = winnerIndex === 0;
    const winner = winnerIndex === 0 ? this.p1 : this.p2;
    const loser = winnerIndex === 0 ? this.p2 : this.p1;
    winner.setVictory(true);
    if (!loser.ko) loser.setBlocking(false);
    const stats = this.match.stats[0];
    const accuracy = stats.strikes ? Math.round((stats.landed / stats.strikes) * 100) : 0;
    this.ui.showResult({
      title: playerWon ? "VICTORY" : "DEFEAT",
      playerWon,
      method,
      detail,
      winner: winner.config,
      loser: loser.config,
      stats: [
        { value: `${stats.landed}/${stats.strikes}`, label: "STRIKES LANDED" },
        { value: `${accuracy}%`, label: "ACCURACY" },
        { value: String(stats.takedowns), label: "TAKEDOWNS" },
        { value: String(Math.round(stats.damage)), label: "DAMAGE DEALT" },
      ],
    });
    this.arena.setScreen({ left: playerWon ? this.p1.config.last : this.p2.config.last, right: playerWon ? this.p2.config.last : this.p1.config.last, round: playerWon ? "VICTORY" : "DEFEAT" });
    this.audio.cheer(playerWon ? 2 : 0.7);
    if (playerWon) {
      this.effects.confetti([this.p1.config.accent, 0xf7f2e8, 0xffc14a]);
    }
  }

  showSelect() {
    this.ui.closeAllModals();
    this.ui.hideResult();
    this._disposeFightFighters();
    this.combat.match = null;
    this.match = null;
    this.showcase.forEach((f) => {
      f.root.visible = true;
      f.reset();
    });
    this.selectionRings.forEach((r) => {
      r.visible = true;
    });
    this.state = "select";
    this.ui.showScreen("select");
    this._updateSelectUi();
    this.arena.setScreen({
      left: FIGHTERS[this.selectedIndex].last,
      right: FIGHTER_BY_ID[this.rivalId].last,
      round: "CHOOSE YOUR FIGHTER",
    });
  }

  returnToMenu() {
    this.ui.closeAllModals();
    this.ui.hideResult();
    this._disposeFightFighters();
    this.combat.match = null;
    this.match = null;
    this.showcase.forEach((f) => {
      f.root.visible = true;
      f.reset();
    });
    this.selectionRings.forEach((r) => {
      r.visible = true;
    });
    this.state = "menu";
    this.timeScale = 1;
    this.ui.showScreen("menu");
    this.arena.setScreen({ left: "KAI MORENO", right: "MARCUS OKAFOR", round: "FIGHT NIGHT 07" });
  }

  _updateSelectUi() {
    const fighter = FIGHTERS[this.selectedIndex];
    this.rivalId = RIVALS[fighter.id];
    const rival = FIGHTER_BY_ID[this.rivalId];
    this.ui.buildFighterCards(FIGHTERS);
    this.ui.selectCard(this.selectedIndex, fighter, rival);
    this.selectionRings.forEach((ring, index) => {
      ring.material.color.setHex(FIGHTERS[index].accent);
      ring.material.opacity = index === this.selectedIndex ? 0.9 : 0.14;
    });
  }

  selectFighter(index) {
    if (index === this.selectedIndex) return;
    this.selectedIndex = index;
    this.rivalId = RIVALS[FIGHTERS[index].id];
    this.audio.init();
    this.audio.ui(true);
    this._updateSelectUi();
    this.arena.setScreen({
      left: FIGHTERS[this.selectedIndex].last,
      right: FIGHTER_BY_ID[this.rivalId].last,
      round: "CHOOSE YOUR FIGHTER",
    });
    const fighter = this.showcase[index];
    if (fighter && !fighter.action) fighter.playMove("jab");
  }

  pauseGame() {
    if (!["fight", "roundIntro"].includes(this.state)) return;
    this.pausedFrom = this.state;
    this.state = "paused";
    this.ui.openModal("pause");
    this.app.classList.remove("fight-live");
    this.keyboardBlock = false;
    this.touchBlock = false;
    this.blockHeld = false;
    this.touchMove = { x: 0, y: 0, active: false };
    this._resetJoystick();
  }

  resumeGame() {
    if (this.state !== "paused") return;
    this.state = this.pausedFrom;
    this.ui.closeModal("pause");
    this.app.classList.add("fight-live");
  }

  openHowTo() {
    this.howtoOpen = true;
    if (this.state === "paused") this.ui.closeModal("pause");
    this.ui.openModal("howto");
  }

  closeHowTo() {
    this.howtoOpen = false;
    this.ui.closeModal("howto");
    if (this.state === "paused") this.ui.openModal("pause");
  }

  toggleSound() {
    this.soundEnabled = !this.soundEnabled;
    this.audio.setEnabled(this.soundEnabled);
    this.ui.setSound(this.soundEnabled);
    if (this.soundEnabled) {
      this._ensureAudio();
      this.audio.ui(true);
    }
    try {
      localStorage.setItem("octagon-sound", this.soundEnabled ? "on" : "off");
    } catch {
      /* private mode */
    }
  }

  _ensureAudio() {
    if (!this.soundEnabled) return;
    this.audio.init();
    this.audio.startCrowd();
  }

  getMoveInput() {
    let forward = 0;
    let strafe = 0;
    if (this.keys.has("KeyW") || this.keys.has("ArrowUp")) forward += 1;
    if (this.keys.has("KeyS") || this.keys.has("ArrowDown")) forward -= 1;
    if (this.keys.has("KeyD") || this.keys.has("ArrowRight")) strafe += 1;
    if (this.keys.has("KeyA") || this.keys.has("ArrowLeft")) strafe -= 1;
    if (this.touchMove.active) {
      forward += -this.touchMove.y;
      strafe += this.touchMove.x;
    }
    const length = Math.hypot(forward, strafe);
    if (length > 1) {
      forward /= length;
      strafe /= length;
    }
    return { forward, strafe };
  }

  projectToScreen(position) {
    const v = position.clone().project(this.camera);
    if (v.z > 1 || v.z < -1) return null;
    const rect = this.canvas.getBoundingClientRect();
    return {
      x: (v.x * 0.5 + 0.5) * rect.width,
      y: (-v.y * 0.5 + 0.5) * rect.height,
    };
  }

  _bindInput() {
    document.addEventListener("keydown", (event) => {
      if (["Space", "ArrowUp", "ArrowDown", "ArrowLeft", "ArrowRight"].includes(event.code)) event.preventDefault();
      if (event.repeat) {
        if (["KeyW", "KeyA", "KeyS", "KeyD", "ArrowUp", "ArrowDown", "ArrowLeft", "ArrowRight"].includes(event.code)) {
          this.keys.add(event.code);
        }
        return;
      }
      if (event.code === "Escape") {
        if (this.howtoOpen) {
          this.closeHowTo();
          return;
        }
        if (this.state === "paused") this.resumeGame();
        else if (this.state === "fight" || this.state === "roundIntro") this.pauseGame();
        else if (this.state === "select") this.returnToMenu();
        return;
      }
      if (["KeyW", "KeyA", "KeyS", "KeyD", "ArrowUp", "ArrowDown", "ArrowLeft", "ArrowRight"].includes(event.code)) {
        this.keys.add(event.code);
      }
      if (event.code === "ShiftLeft" || event.code === "ShiftRight") {
        this.keyboardBlock = true;
      }
      if (this.state === "menu" && (event.code === "Enter" || event.code === "Space")) {
        this.showSelect();
        return;
      }
      if (this.state === "select" && event.code === "Enter") {
        this.startFight();
        return;
      }
      if (this.state !== "fight") return;
      if (event.code === "KeyJ") this.combat.attack("jab", true);
      else if (event.code === "KeyK") this.combat.attack("heavy", true);
      else if (event.code === "KeyL") this.combat.attack("kick", true);
      else if (event.code === "Space") this.combat.attack("takedown", true);
      else if (event.code === "KeyP") this.pauseGame();
    });

    document.addEventListener("keyup", (event) => {
      this.keys.delete(event.code);
      if (event.code === "ShiftLeft" || event.code === "ShiftRight") this.keyboardBlock = false;
    });

    window.addEventListener("blur", () => {
      this.keys.clear();
      this.keyboardBlock = false;
    });

    document.addEventListener("visibilitychange", () => {
      if (document.hidden && this.state === "fight") this.pauseGame();
    });

    this.canvas.addEventListener("contextmenu", (event) => event.preventDefault());
    this.canvas.addEventListener("pointerdown", (event) => {
      this._ensureAudio();
      if (this.state !== "fight" || event.pointerType === "touch") return;
      if (event.button === 0) this.combat.attack("jab", true);
      if (event.button === 2) this.combat.attack("heavy", true);
    });

    this._bindTouch();
  }

  _bindTouch() {
    const joystick = document.getElementById("joystick");
    const knob = document.getElementById("joystick-knob");
    let pointerId = null;
    let center = { x: 0, y: 0 };
    const maxDistance = 38;

    const updateStick = (event) => {
      let dx = event.clientX - center.x;
      let dy = event.clientY - center.y;
      const dist = Math.hypot(dx, dy);
      if (dist > maxDistance) {
        dx = (dx / dist) * maxDistance;
        dy = (dy / dist) * maxDistance;
      }
      const nx = dx / maxDistance;
      const ny = dy / maxDistance;
      knob.style.transform = `translate(${dx}px, ${dy}px)`;
      this.touchMove.active = Math.hypot(nx, ny) > 0.12;
      this.touchMove.x = nx;
      this.touchMove.y = ny;
    };

    joystick.addEventListener("pointerdown", (event) => {
      if (this.state !== "fight") return;
      event.preventDefault();
      pointerId = event.pointerId;
      joystick.setPointerCapture(pointerId);
      const rect = joystick.getBoundingClientRect();
      center = { x: rect.left + rect.width / 2, y: rect.top + rect.height / 2 };
      updateStick(event);
    });
    joystick.addEventListener("pointermove", (event) => {
      if (event.pointerId !== pointerId) return;
      event.preventDefault();
      updateStick(event);
    });
    const releaseStick = (event) => {
      if (pointerId !== null && event.pointerId !== pointerId) return;
      pointerId = null;
      this.touchMove = { x: 0, y: 0, active: false };
      knob.style.transform = "translate(0, 0)";
    };
    joystick.addEventListener("pointerup", releaseStick);
    joystick.addEventListener("pointercancel", releaseStick);
    joystick.addEventListener("lostpointercapture", releaseStick);

    document.querySelectorAll("[data-touch]").forEach((button) => {
      const action = button.dataset.touch;
      button.addEventListener("pointerdown", (event) => {
        event.preventDefault();
        this._ensureAudio();
        if (this.state !== "fight") return;
        if (action === "block") {
          this.touchBlock = true;
          button.classList.add("pressed");
          return;
        }
        button.classList.add("pressed");
        this.combat.attack(action, true);
      });
      const release = (event) => {
        event.preventDefault();
        button.classList.remove("pressed");
        if (action === "block") this.touchBlock = false;
      };
      button.addEventListener("pointerup", release);
      button.addEventListener("pointercancel", release);
      button.addEventListener("pointerleave", release);
    });
  }

  _resetJoystick() {
    const knob = document.getElementById("joystick-knob");
    if (knob) knob.style.transform = "translate(0, 0)";
    this.touchMove = { x: 0, y: 0, active: false };
  }

  _bindUi() {
    this.app.addEventListener("pointerdown", () => this._ensureAudio());
    this.app.addEventListener("click", (event) => {
      const card = event.target.closest("[data-fighter]");
      if (card) {
        this.selectFighter(Number(card.dataset.fighter));
        return;
      }
      const actionNode = event.target.closest("[data-action]");
      if (!actionNode) return;
      const action = actionNode.dataset.action;
      this._ensureAudio();
      this.audio.ui(true);
      switch (action) {
        case "select":
          this.showSelect();
          break;
        case "fight":
          this.startFight();
          break;
        case "howto":
          this.openHowTo();
          break;
        case "close-howto":
          this.closeHowTo();
          break;
        case "resume":
          this.resumeGame();
          break;
        case "quit":
          this.returnToMenu();
          break;
        case "rematch":
          this.startFight();
          break;
        case "menu":
          this.returnToMenu();
          break;
        case "sound":
          this.toggleSound();
          break;
        default:
          break;
      }
    });
  }

  _resize() {
    const width = window.innerWidth;
    const height = window.innerHeight;
    this.camera.aspect = width / height;
    this.camera.updateProjectionMatrix();
    this.renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 1.55));
    this.renderer.setSize(width, height);
    if (this.composer) {
      this.composer.setSize(width, height);
      this.bloom.setSize(width, height);
    }
  }

  _loop(now) {
    const dt = Math.min(0.05, Math.max(0.001, (now - this.lastFrame) / 1000));
    this.lastFrame = now;
    this.time += dt;
    this.update(dt);
    this.render();
    requestAnimationFrame(this._loop);
  }

  update(dt) {
    this.arena.update(dt, this.time);
    this.blockHeld = this.keyboardBlock || this.touchBlock;

    switch (this.state) {
      case "menu":
      case "select":
        this._updateShowcase(dt);
        break;
      case "roundIntro":
        this.roundIntroTimer -= dt;
        if (this.p1 && this.p2) {
          this.p1.update(dt, this.time, 0);
          this.p2.update(dt, this.time, 0);
        }
        if (this.roundIntroTimer <= 0) {
          this.state = "fight";
          this.audio.bell(1);
          this.ui.setStatus("FIGHT");
          this.ui.flashStatus("FIGHT", 0.9);
        }
        break;
      case "fight":
        this.combat.update(dt);
        break;
      case "roundEnd":
        this.roundEndTimer -= dt;
        if (this.p1 && this.p2) {
          this.p1.update(dt, this.time, 0);
          this.p2.update(dt, this.time, 0);
        }
        if (this.roundEndTimer <= 0) {
          if (this.combat.isFinalRound()) this.finishDecision();
          else this.beginRound(this.match.round + 1);
        }
        break;
      case "ko":
        this.koTimer += dt;
        const sdt = dt * this.timeScale;
        if (this.p1 && this.p2) {
          this.p1.update(sdt, this.time, 0);
          this.p2.update(sdt, this.time, 0);
        }
        this.timeScale = damp(this.timeScale, this.koTimer > 1.5 ? 0.62 : 0.3, 1.2, dt);
        const koWinner = this.koWinner === 0 ? this.p1 : this.p2;
        const koLoser = this.koWinner === 0 ? this.p2 : this.p1;
        if (koWinner && this.koTimer > 1.15) koWinner.setVictory(true);
        if (this.koTimer > 2.0 && koLoser && koLoser.visual.rotation.x < -1.35) {
          this.koLoserRest = true;
        }
        if (this.koTimer > 4.6) {
          this.finishMatch(this.koWinner, "KO / TKO", this.finishDetail);
        }
        break;
      case "result":
        if (this.p1 && this.p2) {
          this.p1.update(dt, this.time, 0);
          this.p2.update(dt, this.time, 0);
        }
        break;
      case "paused":
        if (this.p1 && this.p2) {
          this.p1.update(0, this.time, 0);
          this.p2.update(0, this.time, 0);
        }
        break;
      default:
        break;
    }

    if (this.match && ["roundIntro", "fight", "roundEnd", "ko", "paused"].includes(this.state)) {
      this.ui.updateHud(this.match);
    }
    this.ui.tickStatus();
    this.effects.update(dt);
    this._updateCamera(dt);
    this.shake *= Math.exp(-5.5 * dt);
  }

  _updateShowcase(dt) {
    const selectMode = this.state === "select";
    this.showcase.forEach((fighter, index) => {
      const targetZ = selectMode ? (index === this.selectedIndex ? 0.36 : -0.08) : 0;
      fighter.root.position.z = damp(fighter.root.position.z, targetZ, 5, dt);
      fighter.setFacing(0, 1, dt);
      fighter.update(dt, this.time, 0);
      fighter.showcaseTimer -= dt;
      if (fighter.showcaseTimer <= 0 && !fighter.action) {
        fighter.showcaseTimer = 2.4 + Math.random() * 3.2;
        const moves = ["jab", "heavy", "jab", "kick"];
        fighter.playMove(moves[(Math.random() * moves.length) | 0]);
      }
      const ring = this.selectionRings[index];
      ring.position.x = fighter.root.position.x;
      ring.position.z = fighter.root.position.z;
      if (selectMode) {
        const selected = index === this.selectedIndex;
        ring.material.opacity = selected ? 0.88 + Math.sin(this.time * 4) * 0.1 : 0.12;
        ring.scale.setScalar(selected ? 1.08 + Math.sin(this.time * 4) * 0.025 : 0.9);
      } else {
        ring.material.opacity = 0.2 + Math.sin(this.time * 2 + index) * 0.04;
        ring.scale.setScalar(0.9);
      }
    });
  }

  _updateCamera(dt) {
    const desired = new THREE.Vector3();
    const look = new THREE.Vector3();
    let targetFov = 50;
    let rate = 5;

    if (this.state === "menu" || this.state === "select") {
      const selectMode = this.state === "select";
      const drift = Math.sin(this.time * 0.13) * 0.16;
      desired.set(selectMode ? -0.1 : -0.25 + drift, selectMode ? 2.95 : 3.25, selectMode ? 4.9 : 5.25);
      look.set(0, selectMode ? 1.25 : 1.22, selectMode ? 0.08 : 0.02);
      targetFov = selectMode ? 48 : 50;
      rate = 3.2;
    } else if (this.state === "roundIntro" || this.state === "fight" || this.state === "paused") {
      if (this.p1 && this.p2) {
        const p1p = this.p1.root.position;
        const p2p = this.p2.root.position;
        const dir = new THREE.Vector3(p2p.x - p1p.x, 0, p2p.z - p1p.z);
        if (dir.lengthSq() < 0.001) dir.set(1, 0, 0);
        dir.normalize();
        const right = new THREE.Vector3(dir.z, 0, -dir.x);
        const mid = new THREE.Vector3((p1p.x + p2p.x) / 2, 0, (p1p.z + p2p.z) / 2);
        desired.copy(mid).addScaledVector(dir, -4.75).addScaledVector(right, 0.55);
        desired.y = 3.16;
        const radius = Math.hypot(desired.x, desired.z);
        if (radius > 5.15) {
          desired.x = (desired.x / radius) * 5.15;
          desired.z = (desired.z / radius) * 5.15;
        }
        look.copy(mid).addScaledVector(dir, 0.32);
        look.y = 1.17;
        targetFov = 51;
        rate = 5.5;
      }
    } else if (this.state === "roundEnd") {
      if (this.p1 && this.p2) {
        const mid = new THREE.Vector3().addVectors(this.p1.root.position, this.p2.root.position).multiplyScalar(0.5);
        desired.copy(mid).add(new THREE.Vector3(-4.5, 3.2, 2.9));
        look.copy(mid).add(new THREE.Vector3(0, 1.1, 0));
      }
      targetFov = 50;
      rate = 3.4;
    } else if (this.state === "ko") {
      if (this.p1 && this.p2) {
        const mid = new THREE.Vector3().addVectors(this.p1.root.position, this.p2.root.position).multiplyScalar(0.5);
        const angle = 0.9 + this.koTimer * 0.2;
        desired.set(mid.x + Math.sin(angle) * 3.6, 2.3 + Math.sin(this.koTimer * 0.35) * 0.3, mid.z + Math.cos(angle) * 3.6);
        look.set(mid.x, 0.98, mid.z);
      }
      targetFov = 45;
      rate = 2.5;
    } else if (this.state === "result") {
      const angle = this.time * 0.12 + 2.3;
      desired.set(Math.sin(angle) * 5.2, 3.1, Math.cos(angle) * 5.2);
      look.set(0, 1.18, 0);
      targetFov = 49;
      rate = 1.6;
    } else {
      desired.set(0, 3.2, 5.3);
      look.set(0, 1.2, 0);
    }

    this.camera.position.lerp(desired, 1 - Math.exp(-rate * dt));
    this.camLook.lerp(look, 1 - Math.exp(-rate * 1.25 * dt));
    this.camera.fov = damp(this.camera.fov, targetFov, 2.5, dt);
    this.camera.updateProjectionMatrix();

    if (this.shake > 0.01) {
      this.camera.position.x += (Math.random() - 0.5) * this.shake * 0.11;
      this.camera.position.y += (Math.random() - 0.5) * this.shake * 0.08;
      this.camera.position.z += (Math.random() - 0.5) * this.shake * 0.09;
    }
    this.camera.lookAt(this.camLook);
  }

  render() {
    if (this.composer) this.composer.render();
    else this.renderer.render(this.scene, this.camera);
  }
}

import { Game } from "./game.js";

function boot() {
  const canvas = document.getElementById("scene");
  const gl = canvas.getContext("webgl2") || canvas.getContext("webgl");
  if (!gl) {
    const loading = document.getElementById("loading");
    if (loading) {
      loading.innerHTML = `
        <div class="loading-mark">OR</div>
        <div class="loading-title">OCTAGON <span>RISE</span></div>
        <p style="max-width:340px;text-align:center;font-size:12px;line-height:1.7;color:rgba(255,255,255,.55);margin-top:18px">
          This fight needs WebGL. Enable hardware acceleration or try a current version of Chrome, Safari, or Firefox.
        </p>`;
    }
    return;
  }
  try {
    new Game();
  } catch (error) {
    console.error("Octagon Rise failed to start", error);
    const loading = document.getElementById("loading");
    if (loading) {
      loading.innerHTML = `
        <div class="loading-mark">!</div>
        <div class="loading-title">CARD <span>CANCELLED</span></div>
        <p style="max-width:360px;text-align:center;font-size:12px;line-height:1.7;color:rgba(255,255,255,.55);margin-top:18px">
          The 3D engine could not start. Reload the page to try again.
        </p>`;
    }
  }
}

if (document.readyState === "loading") {
  document.addEventListener("DOMContentLoaded", boot, { once: true });
} else {
  boot();
}

