import * as THREE from "three";
import { AI_PROFILES, MAX_ROUNDS, MOVES, RING_RADIUS, ROUND_SECONDS } from "./config.js";

const clamp = (v, a, b) => Math.max(a, Math.min(b, v));
const random = (a, b) => a + Math.random() * (b - a);
const forwardFromYaw = (yaw) => new THREE.Vector3(Math.sin(yaw), 0, Math.cos(yaw));

/**
 * Owns all moment-to-moment fight simulation: movement, strikes, stamina,
 * AI decisions, damage, scoring and round data.
 */
export class Combat {
  constructor(game) {
    this.g = game;
    this.match = null;
    this.aiCooldown = 0;
    this.aiBlockTimer = 0;
    this.aiStrafe = Math.random() > 0.5 ? 1 : -1;
    this.aiStrafeTimer = 1.2;
    this.aiReactedAction = null;
    this.knockback = [new THREE.Vector3(), new THREE.Vector3()];
    this.lastPlayerMove = null;
    this.aiTauntTimer = 4;
  }

  begin(p1, p2, rivalProfile) {
    this.p1 = p1;
    this.p2 = p2;
    this.profile = AI_PROFILES[rivalProfile] || AI_PROFILES.okafor;
    this.match = {
      health: [100, 100],
      stamina: [100, 100],
      round: 1,
      roundTime: ROUND_SECONDS,
      roundWins: [0, 0],
      combo: [0, 0],
      comboTimer: [0, 0],
      roundDamage: [0, 0],
      stats: [
        { strikes: 0, landed: 0, damage: 0, takedowns: 0, knockdowns: 0, blocks: 0 },
        { strikes: 0, landed: 0, damage: 0, takedowns: 0, knockdowns: 0, blocks: 0 },
      ],
      lastRoundWin: null,
    };
    this.aiCooldown = 0.9;
    this.aiBlockTimer = 0;
    this.aiReactedAction = null;
    this.knockback[0].set(0, 0, 0);
    this.knockback[1].set(0, 0, 0);
    this.resetRoundState(1, true);
  }

  resetRoundState(round, full = false) {
    const m = this.match;
    if (!m) return;
    m.round = round;
    m.roundTime = ROUND_SECONDS;
    m.combo = [0, 0];
    m.comboTimer = [0, 0];
    m.roundDamage = [0, 0];
    m.stamina = [100, 100];
    if (full) {
      m.health = [100, 100];
      m.roundWins = [0, 0];
      m.stats = [
        { strikes: 0, landed: 0, damage: 0, takedowns: 0, knockdowns: 0, blocks: 0 },
        { strikes: 0, landed: 0, damage: 0, takedowns: 0, knockdowns: 0, blocks: 0 },
      ];
    } else {
      m.health = [Math.min(100, m.health[0] + 9), Math.min(100, m.health[1] + 9)];
    }
    this.aiCooldown = 0.85;
    this.aiBlockTimer = 0;
    this.aiReactedAction = null;
    this.knockback[0].set(0, 0, 0);
    this.knockback[1].set(0, 0, 0);
  }

  update(dt) {
    const g = this.g;
    const m = this.match;
    if (!m || g.state !== "fight") return;

    m.roundTime -= dt;
    if (m.roundTime <= 0) {
      m.roundTime = 0;
      g.onRoundTimeExpired();
      return;
    }

    for (let i = 0; i < 2; i++) {
      if (m.comboTimer[i] > 0) m.comboTimer[i] -= dt;
      else m.combo[i] = 0;
    }

    const p1 = this.p1;
    const p2 = this.p2;

    // Player block state
    if (!p1.downed && !p1.ko) {

    this.el.stance.textContent = p1.stance;
  }

  showScreen(name) {
    this.el.menu.classList.toggle("is-active", name === "menu");
    this.el.select.classList.toggle("is-active", name === "select");
    this.el.hud.classList.toggle("is-active", name === "fight");
    this.el.result.classList.toggle("is-active", name === "result");
    document.getElementById("app").classList.toggle("fight-live", name === "fight");
    this.el.touch.setAttribute("aria-hidden", name === "fight" ? "false" : "true");
  }

  hideLoading() {
    this.el.loading.classList.add("done");
  }

  setSound(enabled) {
    this.el.sound.classList.toggle("is-off", !enabled);
    this.el.sound.setAttribute("aria-pressed", String(enabled));
  }

  openModal(id) {
    document.getElementById(id)?.classList.add("is-open");
  }

  closeModal(id) {
    document.getElementById(id)?.classList.remove("is-open");
  }

  closeAllModals() {
    document.querySelectorAll(".modal").forEach((modal) => modal.classList.remove("is-open"));
  }

  resetForRound(round, time) {
    this.el.timer.textContent = this.formatTime(time);
    this.el.timer.classList.remove("is-low");
    this.el.roundLabel.textContent = `ROUND ${round}`;
    this.statusDefault = "";
    this.statusText("");
    this.lastRound = round;
  }

  formatTime(seconds) {
    const s = Math.max(0, Math.ceil(seconds));
    return `${Math.floor(s / 60)}:${String(s % 60).padStart(2, "0")}`;
  }

  updateHud(match, p1, p2) {
    if (!match) return;
    const hp = match.health;
    const stamina = match.stamina;
    this._bar("hud-p1-health", hp[0] / 100);
    this._bar("hud-p1-ghost", hp[0] / 100);
    this._bar("hud-p2-health", hp[1] / 100);
    this._bar("hud-p2-ghost", hp[1] / 100);
    this._bar("hud-p1-stamina", stamina[0] / 100);
    this._bar("hud-p2-stamina", stamina[1] / 100);

    document.getElementById("hud-p1-stamina").parentElement.classList.toggle("low", stamina[0] < 22);
    document.getElementById("hud-p2-stamina").parentElement.classList.toggle("low", stamina[1] < 22);

    this.el.timer.textContent = this.formatTime(match.roundTime);
    this.el.timer.classList.toggle("is-low", match.roundTime <= 10);
    this.el.roundLabel.textContent = `ROUND ${match.round}`;
    this.el.staminaLabel.textContent = String(Math.round(stamina[0]));

    for (let i = 0; i < 3; i++) {
      const p1El = document.getElementById("pips-p1").children[i];
      const p2El = document.getElementById("pips-p2").children[i];
      if (p1El) p1El.classList.toggle("won", i < match.roundWins[0]);
      if (p2El) p2El.classList.toggle("won", i < match.roundWins[1]);
    }

    const combo = match.combo[0];
    if (combo >= 2 && match.comboTimer[0] > 0) {
      this.el.combo.classList.add("show");
      this.el.comboNum.textContent = String(combo);
    } else {
      this.el.combo.classList.remove("show");
    }

