    if (this.p1 && this.p2) {
      const mid = new THREE.Vector3().addVectors(this.p1.root.position, this.p2.root.position).multiplyScalar(0.5);
      const angle = 0.9 + this.koTimer * 0.2;
      desired.set(mid.x + Math.sin(angle) * 4.6, 3.0 + Math.sin(this.koTimer * 0.35) * 0.25, mid.z + Math.cos(angle) * 4.6);
